"use client";

import { useState } from "react";
import Link from "next/link";
import { useWorkspaceRead } from "@/components/cafe/use-workspace-read";
import { PageHeader, LoadingState } from "@/components/cafe/ui";
import { money } from "@/lib/client";
import { dateStrInTz } from "@/lib/date-range";
import { useApp } from "@/components/app-shell";
import {ReportingControls,type ReportingMetadata} from '@/components/sales/reporting-controls';
import {ReportOutputActions} from '@/components/sales/report-output-actions';
import {TouchSelect} from '@/components/pos/touch-select';
import { DAILY_REPORT_METRICS, type DailyMetricKey } from "@/lib/metric-definitions";
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

type Report = {
  reporting:ReportingMetadata;
  outputSnapshot:string;
  date: string;
  totals: {
    orders: number;
    cancelled: number;
    gross: number;
    discounts: number;
    service: number;
    tax: number;
    revenue: number;
    revenueExTax?: number;
    avgOrderValue: number;
  };
  financials: {
    grossSales: number;
    refunds: number;
    salesRefunds: number;
    unservedRefunds: number;
    netSales: number;
    collections: number;
    netMoneyMovement: number;
    cashRefunds: number;
    cardRefunds: number;
  };
  salesByStaff?: {
    userId: string; name: string;
    grossSales: number; refunds: number; netSales: number; orders: number;
  }[];
  collection: {
    paidTotal: number;
    uncollectedTotal: number;
    pendingCount: number;
    pendingRemaining: number;
    partialCount: number;
    partialRemaining: number;
  };
  shifts: { open: number; closed: number; cashDifferenceTotal: number };
  tables?: {
    openCount: number;
    closedTodayCount: number;
    avgSittingMinutes: number;
    collectedTotal: number;
    collectedCount: number;
    uncollectedTotal: number;
    closedSales: number;
  };
  purchases?: {
    total: number;
    invoiceCount: number;
    supplierPayments: number;
    unpaidTotal: number;
    unpaidAsOf?: string;
    draftCount?: number;
    draftTotal?: number;
  };
  byPaymentMethod: { method: string; amount: number; count: number }[];
  byBranch: { branchId: string; branchName: string; revenue: number; orders: number }[];
  byCashier: { cashierId: string; cashierName: string; amount: number; count: number }[];
  items: { product: string; variant: string | null; quantity: number; revenue: number }[];
};

const METHOD_LABELS: Record<string, string>
 = {
  CASH: "كاش",
  CARD: "فيزا",
  WALLET: "محفظة",
  MIXED: "مختلط",
};

export default function ReportsPage() {
  const { cafe, canKey, user } = useApp();
  const currency = cafe?.currency ?? "USD";
  const [filters,setFilters]=useState<Record<string,string>>({reportMode:'business',businessFrom:dateStrInTz(new Date()),businessTo:dateStrInTz(new Date())});
  const query='/api/reports/daily?'+new URLSearchParams(Object.fromEntries(Object.entries(filters).filter(([,v])=>v)));
  const {data:report,error,loading,refresh:load}=useWorkspaceRead<Report>(query,`${user.id}:${user.cafeId}:${user.branchId}`);

  return (
    <div className="workspace-page min-w-0">
      <PageHeader title="تقرير قفلة اليوم">
        <TouchSelect aria-label="فرع التقرير" value={filters.branchId??''} onValueChange={v=>setFilters({...filters,branchId:v})}><option value="">كل الفروع المسموحة — كل فرع بساعاته</option>{report?.reporting.branches.map(b=><option key={b.id} value={b.id}>{b.name}</option>)}</TouchSelect>
      </PageHeader>
      <details className="text-sm"><summary className="inline-flex cursor-pointer items-center gap-2 text-primary">تقارير مرتبطة</summary><nav aria-label="تقارير مرتبطة" className="mt-2 flex flex-wrap gap-4 rounded-xl bg-card p-4">
      {(user.role === "CAFE_OWNER" || user.role === "SUPER_ADMIN") && canKey("finance.view_revenue") && (
        <><Link className="inline-block text-primary underline" href="/reports/historical-sales">المبيعات التاريخية المستوردة من Next Cup خلال السنة</Link></>
      )}
      <Link className="inline-block text-primary underline" href="/reports/opening-receipts">تقرير استلام الكاش والخامات والمكان — المطابق والمؤجل والفروق</Link>
      <Link className="inline-block text-primary underline" href="/reports/employee-variances">تقرير فروق الموظفين — كاش وفيزا ومحفظة وخامات</Link>
      <Link className="inline-block text-primary underline" href="/reports/employee-actions">تقرير مسؤولية الموظفين عن الإلغاء والاسترداد</Link>
      <Link href="/report-center" className="text-primary underline">كل التقارير</Link></nav></details>
      <ReportingControls filters={filters} onChange={setFilters} metadata={report?.reporting} onSaved={()=>void load()}/>
      {loading&&<LoadingState label="جاري تحديث فترة التقرير…" />}
      {error&&<p role="alert" className="rounded border p-3 text-destructive">{error} <button className="ms-3 underline" onClick={load}>إعادة المحاولة</button> {report ? "المعروض آخر تقرير ناجح لنفس النطاق؛ التصدير متوقف حتى التحديث." : "لم تتوفر بيانات لهذا النطاق."}</p>}
      <ReportOutputActions snapshot={report?.outputSnapshot} disabled={loading||!!error}/>

      {report && (
        <>
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
            {([
              { metric: "grossSales", value: money(report.financials.grossSales, currency) },
              { metric: "salesRefunds", value: money(report.financials.salesRefunds, currency) },
              { metric: "netSales", value: money(report.financials.netSales, currency) },
              { metric: "collections", value: money(report.financials.collections, currency) },
              { metric: "refunds", value: money(report.financials.refunds, currency) },
              { metric: "unservedRefunds", value: money(report.financials.unservedRefunds, currency) },
              { metric: "netMoneyMovement", value: money(report.financials.netMoneyMovement, currency) },
              ...(report.totals.revenueExTax !== undefined
                ? [{ metric: "revenueExTax", value: money(report.totals.revenueExTax, currency) }]
                : []),
              { metric: "orders", value: String(report.totals.orders) },
              { metric: "avgOrderValue", value: money(report.totals.avgOrderValue, currency) },
              { metric: "discounts", value: money(report.totals.discounts, currency) },
              { metric: "openShifts", value: String(report.shifts.open) },
              { metric: "closedShifts", value: String(report.shifts.closed) },
              { metric: "cashDifferenceTotal", value: money(report.shifts.cashDifferenceTotal, currency) },
              { metric: "service", value: money(report.totals.service, currency) },
              { metric: "tax", value: money(report.totals.tax, currency) },
              { metric: "pendingCount", value: String(report.collection.pendingCount) },
              { metric: "uncollectedTotal", value: money(report.collection.uncollectedTotal, currency) },
              { metric: "partialRemaining", value: money(report.collection.partialRemaining, currency) },
              ...(report.tables
                ? [
                    { metric: "openTables", value: String(report.tables.openCount) },
                    { metric: "closedTables", value: String(report.tables.closedTodayCount) },
                    { metric: "avgSittingMinutes", value: `${report.tables.avgSittingMinutes} دقيقة` },
                    { metric: "tableCollections", value: money(report.tables.collectedTotal, currency) },
                    { metric: "tableUncollected", value: money(report.tables.uncollectedTotal, currency) },
                  ]
                : []),
              ...(report.purchases
                ? [
                    { metric: "purchases", value: money(report.purchases.total, currency) },
                    { metric: "supplierPayments", value: money(report.purchases.supplierPayments, currency) },
                    { metric: "supplierUnpaid", value: money(report.purchases.unpaidTotal, currency) },
                    {
                      metric: "purchaseDrafts", suffix: ` (${report.purchases.draftCount ?? 0})`,
                      value: money(report.purchases.draftTotal ?? 0, currency),
                    },
                  ]
                : []),
            ] as { metric: DailyMetricKey; value: string; suffix?: string }[]).map((stat) => (
              <Card key={stat.metric} title={DAILY_REPORT_METRICS[stat.metric].definition}>
                <CardHeader className="pb-1">
                  <CardTitle className="text-sm font-normal text-muted-foreground">
                    {DAILY_REPORT_METRICS[stat.metric].label}{stat.suffix}
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="text-2xl font-semibold tabular-nums">{stat.value}</p>
                </CardContent>
              </Card>
            ))}
          </div>

          <p className="text-sm text-muted-foreground" data-testid="refund-recognition-note">مرتجعات الطلبات قبل التسليم تؤثر على حركة الأموال فقط.</p>

          <div className="grid gap-4 lg:grid-cols-2">
            <Card>
              <CardHeader>
                <CardTitle className="text-base">المدفوعات حسب الطريقة</CardTitle>
              </CardHeader>
              <CardContent>
                {report.byPaymentMethod.length === 0 ? (
                  <p className="text-sm text-muted-foreground">مفيش مدفوعات.</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>الطريقة</TableHead>
                        <TableHead className="text-end">عدد العمليات</TableHead>
                        <TableHead className="text-end">المبلغ</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {report.byPaymentMethod.map((p) => (
                        <TableRow key={p.method}>
                          <TableCell>{METHOD_LABELS[p.method] ?? p.method}</TableCell>
                          <TableCell className="text-end tabular-nums">{p.count}</TableCell>
                          <TableCell className="text-end tabular-nums">
                            {money(p.amount, currency)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>

            <Card>
              <CardHeader>
                <CardTitle className="text-base">المبيعات حسب الفرع</CardTitle>
              </CardHeader>
              <CardContent>
                {report.byBranch.length === 0 ? (
                  <p className="text-sm text-muted-foreground">مفيش طلبات مكتملة.</p>
                ) : (
                  <Table>
                    <TableHeader>
                      <TableRow>
                        <TableHead>الفرع</TableHead>
                        <TableHead className="text-end">الطلبات</TableHead>
                        <TableHead className="text-end">المبيعات</TableHead>
                      </TableRow>
                    </TableHeader>
                    <TableBody>
                      {report.byBranch.map((b) => (
                        <TableRow key={b.branchId}>
                          <TableCell>{b.branchName}</TableCell>
                          <TableCell className="text-end tabular-nums">{b.orders}</TableCell>
                          <TableCell className="text-end tabular-nums">
                            {money(b.revenue, currency)}
                          </TableCell>
                        </TableRow>
                      ))}
                    </TableBody>
                  </Table>
                )}
              </CardContent>
            </Card>
          </div>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">تحصيلات كل كاشير</CardTitle>
            </CardHeader>
            <CardContent>
              {report.byCashier.length === 0 ? (
                <p className="text-sm text-muted-foreground">مفيش مبيعات.</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>الكاشير</TableHead>
                      <TableHead className="text-end">عدد العمليات</TableHead>
                      <TableHead className="text-end">المبلغ</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {report.byCashier.map((c) => (
                      <TableRow key={c.cashierId}>
                        <TableCell>{c.cashierName}</TableCell>
                        <TableCell className="text-end tabular-nums">{c.count}</TableCell>
                        <TableCell className="text-end tabular-nums">
                          {money(c.amount, currency)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">مبيعات الأصناف</CardTitle>
            </CardHeader>
            <CardContent>
              {report.items.length === 0 ? (
                <p className="text-sm text-muted-foreground">مفيش أصناف اتباعت.</p>
              ) : (
                <Table>
                  <TableHeader>
                    <TableRow>
                      <TableHead>المنتج</TableHead>
                      <TableHead>الحجم</TableHead>
                      <TableHead className="text-end">الكمية</TableHead>
                      <TableHead className="text-end">المبيعات</TableHead>
                    </TableRow>
                  </TableHeader>
                  <TableBody>
                    {report.items.map((item, i) => (
                      <TableRow key={i}>
                        <TableCell className="font-medium">{item.product}</TableCell>
                        <TableCell>{item.variant ?? "—"}</TableCell>
                        <TableCell className="text-end tabular-nums">{item.quantity}</TableCell>
                        <TableCell className="text-end tabular-nums">
                          {money(item.revenue, currency)}
                        </TableCell>
                      </TableRow>
                    ))}
                  </TableBody>
                </Table>
              )}
            </CardContent>
          </Card>

          {report.totals.cancelled > 0 && (
            <p className="text-sm text-muted-foreground">
              عدد {report.totals.cancelled} طلب اتلغى في اليوم ده.
            </p>
          )}
        </>
      )}
    </div>
  );
}

