@import "tailwindcss";
@import "tw-animate-css";
@import "shadcn/tailwind.css";

/* artifacts/ holds ~77k evidence files; scanning them makes PostCSS time out in dev. */
@source not "../../artifacts";
@source not "../../local-restore";

/* Cashier controls retain the same sizing for touch, keyboard and mouse. */
html[data-cashier-touch="true"] :is(button, [role="button"], a[href], select, summary, [role="option"], [role="tab"], [role="menuitem"], input:not([type="checkbox"]):not([type="radio"]):not([type="hidden"]), textarea) {
  min-height: 48px;
  min-width: 48px;
  height: auto;
  white-space: normal;
  overflow-wrap: anywhere;
  touch-action: manipulation;
  scroll-margin-block: 1rem;
}
html[data-cashier-touch="true"] :is(button, [role="button"], a[href], select, summary, [role="option"], [role="tab"], [role="menuitem"]) { padding-block: .65rem; }
html[data-cashier-touch="true"] :is(input, select, textarea) { font-size: 16px; }
html[data-cashier-touch="true"] :is(button, [role="button"], a[href]):focus-visible { outline: 3px solid var(--primary); outline-offset: 2px; }
html[data-cashier-touch="true"] button:active:not(:disabled) { filter: brightness(.92); }
html[data-cashier-touch="true"] label:has(> input:is([type="checkbox"], [type="radio"])) { display: flex; align-items: center; gap: 12px; min-height: 48px; min-width: 48px; padding: 8px; }
html[data-cashier-touch="true"] input:is([type="checkbox"], [type="radio"]) { width: 24px; height: 24px; flex-shrink: 0; }
html[data-cashier-touch="true"] nav { gap: 8px; }
html[data-cashier-touch="true"] nav a { margin-bottom: 8px; }
@media (max-height: 760px) { html[data-cashier-touch="true"] aside nav :is(a[href], button) { min-height: 36px; padding-block: 0.375rem; margin-bottom: 2px; } }
html[data-cashier-touch="true"] :is([class~="gap-1"], [class~="gap-1.5"]) { gap: 8px; }
html[data-cashier-touch="true"] [data-slot="dialog-content"] {
  top: calc(var(--cashier-viewport-top, 0px) + var(--cashier-viewport-height, 100dvh) / 2);
  max-height: calc(var(--cashier-viewport-height, 100dvh) - 1rem);
  padding-top: 4rem;
}
html[data-cashier-touch="true"] .cashier-dialog-close { width: 90px; min-width: 90px; height: 48px; gap: 6px; padding-inline: 12px; flex-wrap: nowrap; }
html[data-cashier-touch="true"] .cashier-dialog-back { display: inline; }
html[data-cashier-touch="true"] [data-slot="dialog-actions"] { background: var(--popover); }
html[data-cashier-touch="true"] .touch-number { display: inline-flex; min-width: min(100%, 10rem); max-width: 100%; padding: 0; border: 0; }
html[data-cashier-touch="true"] .touch-number > input { width: 3rem; }
.cashier-workspace { display: grid; grid-template-columns: minmax(0, 1fr); gap: 1rem; border: 0; padding: 0; }
.cashier-catalog { min-height: 0; }
.cashier-cart { height: min(800px, calc(100dvh - 2rem)); }
.cashier-categories { position: sticky; top: 0; z-index: 10; }
.cashier-products { max-height: 55dvh; min-height: 180px; }
.cashier-compact-tabs, .cashier-compact-checkout { display: none; }
@media (min-width: 1100px) {
  .cashier-workspace { grid-template-columns: minmax(0, 1fr) minmax(400px, 460px); align-items: start; }
  .cashier-lead, .cashier-catalog { grid-column: 1; }
  .cashier-catalog, .cashier-cart { height: var(--cashier-workspace-height, calc(100dvh - 6rem)); min-height: 40rem; }
  .cashier-catalog { overflow: hidden; }
  .cashier-cart { grid-column: 2; grid-row: 1 / span 2; position: sticky; top: 1rem; }
  .cashier-products { max-height: none; min-height: 0; }
}
@media (max-width: 1099px) {
  .cashier-workspace { display: flex; height: var(--cashier-workspace-height, calc(100dvh - 10rem)); min-height: 220px; flex-direction: column; gap: 8px; }
  .cashier-compact-tabs { display: flex; flex-shrink: 0; }
  .cashier-compact-tabs > button { flex: 1; }
  .cashier-catalog { flex: 1; min-height: 0; overflow-y: auto; }
  .cashier-cart { flex: 1; min-height: 0; height: auto; }
  .cashier-products { min-height: 160px; max-height: none; }
  .cashier-compact-checkout { display: block; flex-shrink: 0; }
  .category-all-products { display: inline-flex; }
  .cashier-categories :is(.category-pages, .category-navigation) { display: none; }
  .cashier-workspace[data-compact-view="products"] .cashier-cart { display: none; }
  .cashier-workspace[data-compact-view="cart"] :is(.cashier-catalog, .cashier-compact-checkout) { display: none; }
  /* The sticky checkout dock carries the collection controls and the final total (~250px), so the cart needs
     room beside it: scroll the page rather than leave a few pixels of cart above the dock. */
  .cashier-workspace[data-compact-view="cart"] { min-height: 36rem; }
}
@media (max-height: 500px) {
  html[data-cashier-touch="true"] [data-slot="dialog-content"] { padding-top: 3.5rem; }
  html[data-cashier-touch="true"] .touch-keypad [data-slot="dialog-scroll-area"] { gap: 8px; }
}
/* Short compact viewports (landscape phone, on-screen keyboard): the 220px workspace floor leaves the
   catalog a ~46px scrollport that the 86px sticky category block fills completely, so no product card is
   reachable. In the products view let the content grow and the page scroll instead. */
@media (max-width: 1099px) and (max-height: 500px) {
  .cashier-workspace[data-compact-view="products"] { height: auto; min-height: 0; }
  .cashier-workspace[data-compact-view="products"] .cashier-catalog { flex: none; overflow: visible; }
  .cashier-workspace[data-compact-view="products"] .cashier-categories { position: static; }
  .cashier-workspace[data-compact-view="products"] .cashier-products { flex: none; overflow-y: visible; }
}

