  --sidebar-primary: var(--color-emerald-700);
  --sidebar-primary-foreground: var(--color-white);
  --sidebar-accent: rgb(255 255 255 / 5%);
  --sidebar-accent-foreground: var(--color-white);
  --sidebar-border: rgb(255 255 255 / 10%);
  --sidebar-ring: var(--color-emerald-400);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
  html {
    @apply font-sans;
  }
}

/* NEXT CUP workspace language: normal browser/user text scaling is retained. */
.app-workspace { font-size: 1rem; line-height: 1.6; }
.workspace-content { width: 100%; }
.workspace-page { width: 100%; min-width: 0; display: flex; flex-direction: column; gap: 1.5rem; }
.workspace-header h1 { font-size: 1.75rem; line-height: 1.35; font-weight: 750; }
.workspace-toolbar { display: flex; flex-wrap: wrap; align-items: end; gap: 1rem; padding: 1rem; background: var(--card); border-radius: .875rem; }
.workspace-toolbar > label { flex: 1 1 11rem; }
.workspace-surface { background: var(--card); border: 1px solid var(--border); border-radius: 1rem; overflow: hidden; }
.workspace-state { padding: 2.5rem 1.5rem; text-align: center; background: var(--card); border-radius: 1rem; }
.workspace-tabs { display: flex; flex-wrap: wrap; gap: .5rem; border-bottom: 1px solid var(--border); padding-bottom: .75rem; }
.workspace-tabs :is(a,button) { padding: .65rem 1rem; border-radius: .65rem; min-height: 44px; }
.workspace-table { width: 100%; border-collapse: collapse; text-align: start; font-size: .9375rem; }
.workspace-table :is(th,td) { text-align: start; padding: 1rem; border-bottom: 1px solid var(--border); vertical-align: middle; }
.workspace-table th { background: var(--muted); color: var(--muted-foreground); font-size: .875rem; font-weight: 600; white-space: nowrap; }
.workspace-table tbody tr:hover { background: var(--sage-soft); }
.app-workspace :is(input:not([type=checkbox]):not([type=radio]),select,textarea) { font-size: 1rem; min-height: 44px; }
.app-workspace :is(button,[role=button],summary) { min-height: 44px; }
.app-workspace :is(button,a,input,select,textarea,summary):focus-visible { outline: 2px solid var(--ring); outline-offset: 3px; }
.workspace-nav-link { min-height: 44px; }
.workspace-sidebar [data-nav-rail] { min-width: 0; }
[data-nav-rail=true] > .workspace-sidebar :is(.workspace-nav-label,.workspace-nav-group) { display: none; }
[data-nav-rail=true] > .workspace-sidebar .workspace-nav-link { justify-content: center; padding-inline: .5rem; }
[data-nav-rail=true] > .workspace-sidebar > :is(div,nav) { padding-inline: .5rem; }
[data-nav-rail=true] > .workspace-sidebar .workspace-nav-link + .workspace-nav-link { margin-top: .25rem; }
@media (max-width: 767px) {
  .workspace-header h1 { font-size: 1.625rem; }
  .workspace-page { gap: 1rem; }
  .workspace-toolbar { gap: .75rem; padding: .875rem; }
  .workspace-table :is(th,td) { padding: .875rem; }
}
@media print { .workspace-content { padding: 0; } }

@media (min-width:1100px) {
 .cashier-workspace { grid-template-columns:minmax(0,1fr) minmax(350px,400px); grid-template-rows:auto minmax(0,1fr); }
 .cashier-lead { grid-column:1 / -1; }
 .cashier-catalog { grid-row:2; grid-column:1; }
 .cashier-cart { grid-row:2; grid-column:2; }
 .cashier-catalog,.cashier-cart { height:var(--cashier-workspace-height,calc(100dvh - 12rem)); min-height:360px; }
 .cashier-products { grid-template-columns:repeat(auto-fill,minmax(165px,1fr)); }
}
.cashier-product { min-height:160px; }
.cashier-catalog-state { min-height:220px; }
.workspace-content > .cashier-page { min-width:0; }
.app-workspace [data-slot=table-container] { max-width:100%; }

/* One rhythm, including pages retaining their earlier space-y utilities. */
.workspace-page { display:block; }
.workspace-page > * { margin-block-start:0; }
.workspace-page > * + * { margin-block-start:1.25rem; }
.workspace-page > .workspace-header { margin-block-end:0; }

@media (min-width:1100px) {
 .sales-filterbar { display:grid; grid-template-columns:minmax(0,1.5fr) minmax(240px,1fr); gap:1rem; }
 .sales-filterbar > * { margin-block:0; min-width:0; }
 .sales-filterbar > .reporting-controls { grid-column:1; }
 .sales-filterbar > form { grid-column:2; grid-row:1; align-self:start; }
 .sales-filterbar > details,.sales-filterbar > [aria-label] { grid-column:1 / -1; }
 .sales-filterbar > .reporting-controls { grid-column:1; }
}

