  { href: "/stock-counts", label: "جرد المخزون", icon: "📋", permission: "inventory:read", group: "stock", key: "stock_count.view", feature: (f) => f.inventoryEnabled },
  { href: "/variances", label: "الفروقات", icon: "⚖️", permission: "shifts:read", group: "stock", key: "variance.view", feature: (f) => f.shiftManagementEnabled },
  { href: "/handovers", label: "التسليم والاستلام", icon: "🤝", permission: "shifts:operate", group: "stock", key: "handover.view", feature: (f) => f.shiftManagementEnabled },
  { href: "/reports", label: t.nav.reports, icon: "📈", permission: "reports:read", group: "reports" },
  { href: "/expenses", label: "المصروفات", icon: "💸", permission: "cost:read", group: "finance", key: "expenses.view" },
  { href: "/accounting", label: "المحاسبة (تجريبي)", icon: "📒", permission: "cost:read", group: "finance", key: "accounting.view" },
  { href: "/shifts", label: t.nav.shiftReports, icon: "🧮", permission: "shifts:read", group: "reports", feature: (f) => f.shiftManagementEnabled },
  { href: "/settings", label: "الإعدادات", icon: "⚙️", permission: "branches:manage", group: "admin" },
  { href: "/roles-permissions", label: "الأدوار والصلاحيات", icon: "🛡️", permission: "users:manage", group: "admin", key: "users.manage_permissions" },
  { href: "/audit", label: t.nav.audit, icon: "🕓", permission: "audit:read", group: "reports" },
];

export function AppShell({
  user,
  cafe,
  branchName,
  features,
  permKeys,
  children,
}: {
  user: SessionUser;
  cafe: AppContextValue["cafe"];
  branchName: string | null;
  features: CafeFeatures | null;
  permKeys: string[];
  children: React.ReactNode;
}) {
  const pathname = usePathname();
  const cashierTouch = ["/pos", "/orders", "/sales", "/tracing", "/tables", "/current-shift", "/close-shift", "/receipts", "/reports", "/handovers", "/stock-counts"].some(route => pathname === route || pathname.startsWith(route + "/"));
  const router = useRouter();
  const [mobileNavOpen, setMobileNavOpen] = useState(false);
  const [rail, setRail] = useState(false);
  useEffect(() => {
    const desktop = window.matchMedia("(min-width: 768px)");
    const closeOnDesktop = () => { if (desktop.matches) setMobileNavOpen(false); };
    desktop.addEventListener("change", closeOnDesktop);
    return () => desktop.removeEventListener("change", closeOnDesktop);
  }, []);
  const keySet = new Set(permKeys);
  const canKey = (key: string) => keySet.has(key);
  // Legacy Permission → its canonical key, then membership in the effective set.
  const can = (permission: Permission) => {
    const key = primaryKey(permission);
    return key ? keySet.has(key) : false;
  };

  const navItems = NAV.filter(
    (item) =>
      // An explicit `key` (new granular gate) wins; else fall back to the
      // legacy permission bridge.
      (!item.ownerOnly || user.role === "CAFE_OWNER") &&
      (item.anyKey ? item.anyKey.some(canKey) : item.key ? canKey(item.key) : can(item.permission)) &&
      (!item.feature || !features || item.feature(features))
  );

  // Sidebar sections. The server and the first client render show every
  // section open (no hydration mismatch); after mount the saved choice is
  // applied, and on a short screen with no saved choice the sections start
  // collapsed. The section that holds the current page is always open.
  const [collapsedGroups, setCollapsedGroups] = useState<NavGroupId[]>(NAV_GROUPS.map(group=>group.id));
  useEffect(() => {
    const valid = (v: unknown): v is NavGroupId => NAV_GROUPS.some((g) => g.id === v);
    const timer = window.setTimeout(() => {
      let saved: NavGroupId[] | null = null;
      try {
        const raw = window.localStorage.getItem(NAV_COLLAPSED_KEY);
        const parsed: unknown = raw ? JSON.parse(raw) : null;
        if (Array.isArray(parsed)) saved = parsed.filter(valid);
      } catch { /* storage unavailable or corrupt: fall back to the default */ }
      if (saved) setCollapsedGroups(saved);
      else setCollapsedGroups(NAV_GROUPS.map((g) => g.id));
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);
  const currentHref = currentWorkspaceHref(pathname, navItems.map(item => item.href));
  const activeGroup = navItems.find(item => item.href === currentHref)?.group;
  function toggleGroup(id: NavGroupId) {
    setCollapsedGroups((current) => {
      const next = current.includes(id) ? current.filter((g) => g !== id) : [...current, id];
      try { window.localStorage.setItem(NAV_COLLAPSED_KEY, JSON.stringify(next)); } catch { /* not critical */ }
      return next;
    });
  }

  // Pending QR-approval count for the sidebar badge (assignment-aware,
  // lightweight 20s poll — only for users who can act on the queue).
  const [pendingQr, setPendingQr] = useState(0);
  const canSeeQr = canKey("qr_orders.view") || canKey("qr_orders.approve");
  useEffect(() => {
    if (!canSeeQr || !features?.qrMenuEnabled) return;
    let stop = false;
    const tick = () =>
      fetch("/api/qr-orders/pending?countOnly=1")
        .then((r) => (r.ok ? r.json() : { count: 0 }))
        .then((d) => { if (!stop) setPendingQr(d.count ?? 0); })
        .catch(() => {});
    tick();
    const timer = setInterval(tick, 20_000);
    return () => { stop = true; clearInterval(timer); };
  }, [canSeeQr, features?.qrMenuEnabled, pathname]);

  // Refresh branch and role after an owner edit while this page stays open.
  useEffect(() => {
    let stopped = false;
    const check = async () => {
      try {
        const response = await fetch("/api/auth/me", { cache: "no-store" });
        if (!response.ok) return;
        const { user: current } = await response.json() as { user: SessionUser };
        if (!stopped && (current.branchId !== user.branchId ||
            current.cafeId !== user.cafeId || current.role !== user.role ||
            current.name !== user.name)) router.refresh();
      } catch { /* Keep the current view during temporary connection failures. */ }
    };
    const onFocus = () => { void check(); };
    window.addEventListener("focus", onFocus);
    const timer = setInterval(onFocus, 20_000);
    return () => {
      stopped = true;
      window.removeEventListener("focus", onFocus);
      clearInterval(timer);
    };
  }, [router, user.branchId, user.cafeId, user.role, user.name]);

  async function logout() {
    await fetch("/api/auth/logout", { method: "POST" });
    router.push("/login");
    router.refresh();
  }

  const initials = user.name.slice(0, 2);
  const showStockBanner =
    (user.role === "CAFE_OWNER" || user.role === "BRANCH_MANAGER") &&
    can("inventory:read") &&
    (!features || features.inventoryEnabled);
  const showStaleBanner =
    (user.role === "CAFE_OWNER" || user.role === "BRANCH_MANAGER") && can("orders:read");

  const navLink = (item: NavItem) => {
    const active = currentHref === item.href;
    const ancestor = !active && pathname.startsWith(item.href + "/");
    const Icon = NAV_ICONS[item.href] ?? BookOpen;
    return (
      <Link
        key={item.href}
        href={item.href}
        onClick={() => setMobileNavOpen(false)}
        aria-current={active ? "page" : undefined}
        aria-label={item.label}
        title={item.label}
        className={cn(
          "workspace-nav-link flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sidebar-ring",
          ancestor && "border-s-2 border-sidebar-primary",
          active
            ? "bg-sidebar-primary text-sidebar-primary-foreground shadow-sm"
            : "text-sidebar-foreground hover:bg-sidebar-accent hover:text-sidebar-accent-foreground"
        )}
      >
        <Icon aria-hidden="true" className="size-5 shrink-0" />
        <span className="workspace-nav-label flex-1">{item.label}</span>
        {item.href === "/approvals" && pendingQr > 0 && (
          <span className="flex min-w-5 items-center justify-center rounded-full bg-red-500 px-1.5 text-xs font-bold text-white">
            {pendingQr}
          </span>
        )}
      </Link>
    );
  };

  const sidebarContent = (
    <>
          <div className="flex items-center gap-3 border-b border-sidebar-border px-5 py-5 [@media(max-height:760px)]:py-3">
            <span className="flex size-10 items-center justify-center rounded-xl bg-sidebar-primary text-xl text-sidebar-primary-foreground shadow-sm">
              <Coffee className="size-6" aria-hidden="true" />
            </span>
            <div className="workspace-nav-label min-w-0">
              <p className="font-heading text-base font-bold tracking-wider text-sidebar-accent-foreground" dir="ltr">NEXT CUP</p>
              <p className="truncate text-xs" title={cafe?.name}>{cafe?.name ?? t.appName}</p>
              {/^workspace\d{8}-/.test(cafe?.name ?? "") && <p className="mt-1 text-xs text-amber-200">بيانات اصطناعية · معاينة فقط</p>}
              <p className="truncate text-xs text-sidebar-muted-foreground">
                {branchName ?? t.appName}
              </p>
            </div>
          </div>

          <nav aria-label="التنقل الرئيسي" className="min-h-0 flex-1 space-y-0.5 overflow-y-auto overscroll-contain p-3 [@media(max-height:760px)]:p-2">
            {navItems.filter((item) => !item.group).map(navLink)}
            {NAV_GROUPS.map((group) => {
              const items = navItems.filter((item) => item.group === group.id);
              if (items.length === 0) return null;
              const isCurrent = group.id === activeGroup;
              const open = rail || isCurrent || !collapsedGroups.includes(group.id);
              // A collapsed section must not hide a waiting QR approval.
              const badge = !open && items.some((item) => item.href === "/approvals") ? pendingQr : 0;
              return (
                <div key={group.id} className="pt-1.5">
                  <button
                    type="button"
                    onClick={() => { if (!isCurrent) toggleGroup(group.id); }}
                    aria-expanded={open}
                    aria-controls={`nav-group-${group.id}`}
                    aria-disabled={isCurrent || undefined}
                    className="workspace-nav-group flex w-full items-center gap-2 rounded-md px-3 py-1.5 text-xs font-semibold text-sidebar-muted-foreground transition-colors hover:text-sidebar-accent-foreground focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sidebar-ring"
                  >
                    <span className="flex-1 text-start">{group.label}</span>
                    {badge > 0 && (
                      <span className="flex min-w-5 items-center justify-center rounded-full bg-red-500 px-1.5 text-xs font-bold text-white">
                        {badge}
                      </span>
                    )}
                    <ChevronDown aria-hidden="true" className={cn("size-3", !open && "rotate-90")} />
                  </button>
                  <div id={`nav-group-${group.id}`} hidden={!open} className="space-y-0.5">
                    {items.map(navLink)}
                  </div>
                </div>
              );
            })}
          </nav>

          <div className="border-t border-sidebar-border p-4 [@media(max-height:760px)]:p-2.5">
            <div className="mb-3 flex items-center gap-2.5 [@media(max-height:760px)]:mb-2">
              <span className="flex size-9 shrink-0 items-center justify-center rounded-full bg-sidebar-accent-foreground/10 text-xs font-semibold text-sidebar-accent-foreground">
                {initials}
              </span>
              <div className="workspace-nav-label min-w-0">
                <p className="truncate text-sm font-medium text-sidebar-accent-foreground">{user.name}</p>
                <p className="truncate text-xs text-sidebar-muted-foreground">
                  {ROLE_LABELS[user.role]}
                </p>
              </div>
            </div>
            <button
              onClick={logout}
              className="w-full rounded-lg border border-sidebar-accent-foreground/15 px-3 py-2 text-xs font-medium text-sidebar-foreground transition-colors hover:bg-sidebar-accent focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sidebar-ring"
            >
              {t.common.signOut}
            </button>
          </div>
    </>
  );

  return (
    <AppContext.Provider value={{ user, cafe, branchName, can, canKey, permKeys, features }}>
      <CashierTouchViewport active={cashierTouch} />
      <div className="app-workspace flex min-h-screen w-full flex-col bg-workspace md:flex-row" data-nav-rail={rail}>
        <aside className={cn("workspace-sidebar sticky top-0 hidden h-dvh shrink-0 flex-col bg-sidebar text-sidebar-foreground md:flex print:hidden", rail ? "w-20" : "w-64")}>
          <button type="button" className="mx-3 mt-3 flex min-h-10 items-center justify-center gap-2 rounded-lg border border-sidebar-border text-sm hover:bg-sidebar-accent" aria-label={rail ? "توسيع التنقل" : "طي التنقل"} aria-expanded={!rail} onClick={()=>setRail(value=>!value)}>{rail ? <PanelRightOpen className="size-5"/> : <><PanelRightClose className="size-5"/><span>طي التنقل</span></>}</button>
          {sidebarContent}
        </aside>
        <Dialog open={mobileNavOpen} onOpenChange={setMobileNavOpen}>
          <div className="flex items-center gap-3 bg-sidebar px-4 py-3 text-sidebar-foreground md:hidden print:hidden">
            <DialogTrigger className="shrink-0 rounded-lg border border-sidebar-border px-3 py-2 text-sm font-medium focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sidebar-ring">
              القائمة
            </DialogTrigger>
            <p className="min-w-0 truncate text-sm font-semibold text-sidebar-accent-foreground">{cafe?.name ?? t.appName}</p>
          </div>
          <DialogContent scrollable={false} className="flex h-[calc(100dvh-2rem)] max-w-xs flex-col gap-0 overflow-hidden bg-sidebar p-0 pt-10 text-sidebar-foreground">
            <DialogTitle className="sr-only">التنقل الرئيسي</DialogTitle>
            {sidebarContent}
          </DialogContent>
        </Dialog>

        <main key={`${user.id}:${user.cafeId}:${user.branchId}:${user.role}:${permKeys.join(",")}`} className="workspace-content min-w-0 flex-1 p-4 md:p-6 lg:p-8">
          {showStaleBanner && (
            <StaleOrdersBanner pathname={pathname} showBranch={!user.branchId} currency={cafe?.currency ?? "EGP"} />
          )}
          {showStockBanner && <LowStockBanner pathname={pathname} showBranch={!user.branchId} />}
          {children}
        </main>
      </div>
    </AppContext.Provider>
  );
}

src/components/cafe/ui.tsx:
"use client";

// Shared UI kit for the cafe operations app (owner/manager/staff).
// Theme-token based so it adapts to light/dark; semantic accent colors
// for status. Arabic-RTL friendly (logical properties, no truncated money).

import type { OrderStatus, OrderSource } from "@prisma/client";
import { t } from "@/lib/i18n";
import { cn } from "@/lib/utils";

// ── Page header ──────────────────────────────────────────────
export function PageHeader({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: React.ReactNode;
  children?: React.ReactNode;
}) {
  return (
    <div className="workspace-header mb-6 flex flex-wrap items-center justify-between gap-4">
      <div className="min-w-0">
        <h1 className="font-heading text-[1.75rem] leading-snug font-bold tracking-normal text-foreground">
          {title}
        </h1>
        {subtitle && (
          <p className="mt-2 text-base leading-relaxed text-muted-foreground">{subtitle}</p>
        )}
      </div>
      {children && <div className="flex flex-wrap items-center gap-2">{children}</div>}
    </div>
  );
}

// ── Stat card ────────────────────────────────────────────────
const ACCENTS: Record<string, string> = {
  emerald: "bg-sage-soft text-sage-ink",
  amber: "bg-caramel-soft text-caramel-ink",
  red: "bg-clay-soft text-clay-ink",
  blue: "bg-tide-soft text-tide-ink",
  violet: "bg-tide-soft text-tide-ink",
  slate: "bg-foreground/5 text-foreground/70",
};

export function StatCard({
  label,
  value,
  icon,
  hint,
  accent = "slate",
  href,
}: {
  label: string;
  value: string | number;
  icon?: React.ReactNode;
  hint?: React.ReactNode;
  accent?: keyof typeof ACCENTS;
  href?: string;
}) {
  const inner = (
    <div className="flex h-full items-start justify-between gap-3 rounded-2xl border border-border bg-card p-4 shadow-sm transition-shadow hover:shadow-md">
      <div className="min-w-0">
        <p className="text-sm font-medium leading-snug text-muted-foreground">{label}</p>
        <p className="mt-1.5 text-2xl font-bold tabular-nums text-foreground">{value}</p>
        {hint && <div className="mt-1 text-xs text-muted-foreground">{hint}</div>}
      </div>
      {icon && (
        <span className={cn("flex size-10 shrink-0 items-center justify-center rounded-xl text-lg", ACCENTS[accent])}>
          {icon}
        </span>
      )}
    </div>
  );
  if (href) return <a href={href} className="block">{inner}</a>;
  return inner;
}

// ── Panel / ChartCard ────────────────────────────────────────
export function Panel({
  title,
  action,
  className,
  bodyClassName,
  children,
}: {
  title?: string;
  action?: React.ReactNode;
  className?: string;
  bodyClassName?: string;
  children: React.ReactNode;
}) {
  return (
    <section className={cn("rounded-2xl border border-border bg-card text-card-foreground shadow-sm", className)}>
      {(title || action) && (
        <header className="flex items-center justify-between gap-2 border-b border-border/70 px-5 py-3.5">
          {title && <h2 className="font-heading text-base leading-snug font-semibold text-card-foreground">{title}</h2>}
          {action}
        </header>
      )}
      <div className={cn("p-5", bodyClassName)}>{children}</div>
    </section>
  );
}

// ── Status + source badges ───────────────────────────────────
const STATUS_TONE: Record<OrderStatus, string> = {
  PENDING_WAITER_APPROVAL: "bg-amber-500/12 text-amber-700 dark:text-amber-400",
  CONFIRMED: "bg-blue-500/12 text-blue-700 dark:text-blue-400",
  PREPARING: "bg-violet-500/12 text-violet-700 dark:text-violet-400",
  READY: "bg-emerald-500/12 text-emerald-700 dark:text-emerald-400",
  SERVED: "bg-emerald-500/15 text-emerald-700 dark:text-emerald-400",
  CANCELLED: "bg-foreground/8 text-muted-foreground",
  REJECTED: "bg-red-500/12 text-red-700 dark:text-red-400",
};

export function StatusBadge({ status }: { status: OrderStatus }) {
  return (
    <span className={cn("inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium", STATUS_TONE[status])}>
      {t.orderStatus[status]}
    </span>
  );
}

const SOURCE_TONE: Record<OrderSource, string> = {
  QR_MENU: "bg-violet-500/12 text-violet-700 dark:text-violet-400",
  WAITER: "bg-blue-500/12 text-blue-700 dark:text-blue-400",
  CASHIER_POS: "bg-foreground/8 text-foreground/70",
};

export function SourceBadge({ source }: { source: OrderSource }) {
  return (
    <span className={cn("inline-flex items-center rounded-full px-2.5 py-0.5 text-xs font-medium", SOURCE_TONE[source])}>
      {t.orderSource[source]}
    </span>
  );
}

// Generic on/off pill.
export function StatusPill({ active, labels }: { active: boolean; labels: { on: string; off: string } }) {
  return (
    <span
      className={cn(
        "inline-flex items-center gap-1.5 rounded-full px-2.5 py-0.5 text-xs font-medium",
        active ? "bg-emerald-500/12 text-emerald-700 dark:text-emerald-400" : "bg-red-500/12 text-red-700 dark:text-red-400"
      )}
    >
      <span className={cn("size-1.5 rounded-full", active ? "bg-emerald-500" : "bg-red-500")} />
      {active ? labels.on : labels.off}
    </span>
  );
}

// ── Empty / loading states ───────────────────────────────────
export function EmptyState({ message, icon = "🗂️" }: { message: string; icon?: string }) {
  return (
    <div role="status" className="flex flex-col items-center justify-center gap-2 py-12 text-center">
      <span className="text-3xl opacity-50">{icon}</span>
      <p className="text-sm text-muted-foreground">{message}</p>
    </div>
  );
}

export function LoadingState({ label = t.common.loading }: { label?: string }) {
  return (
    <div role="status" aria-live="polite" className="flex items-center justify-center gap-2 py-12 text-sm text-muted-foreground">
      <span className="size-4 animate-spin rounded-full border-2 border-border border-t-foreground/60" />
      {label}
    </div>
  );
}

// ── Charts (inline SVG, dependency-free) ─────────────────────
export function BarChart({
  data,
  color = "var(--chart-bar, #0f766e)",
  format,
}: {
  data: { label: string; value: number; hint?: string }[];
  color?: string;
  format?: (v: number) => string;
}) {
  const max = Math.max(1, ...data.map((d) => d.value));
  return (
    <div className="flex items-end justify-between gap-2" dir="ltr">
      {data.map((d, i) => {
        const h = Math.round((d.value / max) * 100);
        return (
          <div key={i} className="group/bar flex flex-1 flex-col items-center gap-1.5">
            <div className="relative flex h-32 w-full items-end justify-center">
              <span className="pointer-events-none absolute -top-1 -translate-y-full whitespace-nowrap rounded-md border border-border bg-popover px-2 py-1 text-xs opacity-0 shadow-sm transition-opacity group-hover/bar:opacity-100">
                {format ? format(d.value) : d.value}
              </span>
              <div
                className="w-full max-w-9 rounded-t-md transition-all"
                style={{ height: `${Math.max(h, d.value > 0 ? 3 : 0)}%`, backgroundColor: color, opacity: 0.5 + (h / 100) * 0.5 }}
              />
            </div>
            <span className="text-[10px] font-medium text-muted-foreground">{d.label}</span>
          </div>
        );
      })}
    </div>
  );
}

export function RankBars({
  data,
  format,
  emptyLabel = "—",
}: {
  data: { label: string; value: number }[];
  format?: (v: number) => string;
  emptyLabel?: string;
}) {
  const max = Math.max(1, ...data.map((d) => d.value));
  if (data.length === 0) return <EmptyState message={emptyLabel} icon="📊" />;
  return (
    <div className="space-y-2.5">
      {data.map((d, i) => (
        <div key={i} className="space-y-1">
          <div className="flex items-center justify-between gap-2 text-xs">
            <span className="truncate font-medium text-foreground">{d.label}</span>
            <span className="shrink-0 tabular-nums text-muted-foreground">{format ? format(d.value) : d.value}</span>
          </div>
          <div className="h-2 overflow-hidden rounded-full bg-muted">
            <div className="h-full rounded-full bg-emerald-500/80" style={{ width: `${Math.max((d.value / max) * 100, 3)}%` }} />
          </div>
        </div>
      ))}
    </div>
  );
}

const DONUT_COLORS = ["#0f766e", "#2563eb", "#7c3aed", "#d97706", "#dc2626"];

export function Donut({ data }: { data: { label: string; value: number }[] }) {
  const total = data.reduce((s, d) => s + d.value, 0);
  if (total <= 0) return <EmptyState message="—" icon="🥧" />;
  const r = 42;
  const c = 2 * Math.PI * r;
  const dashes = data.map((d) => (d.value / total) * c);
  const segments = dashes.map((dash, i) => ({ dash, offset: dashes.slice(0, i).reduce((a, b) => a + b, 0) }));
  return (
    <div className="flex items-center gap-5">
      <svg viewBox="0 0 100 100" className="size-28 shrink-0 -rotate-90">
        {segments.map((s, i) => (
          <circle
            key={i}
            cx="50" cy="50" r={r} fill="none"
            stroke={DONUT_COLORS[i % DONUT_COLORS.length]} strokeWidth="12"
            strokeDasharray={`${s.dash} ${c - s.dash}`} strokeDashoffset={-s.offset}
          />
        ))}
      </svg>
      <ul className="space-y-1.5 text-xs">
        {data.map((d, i) => (
          <li key={i} className="flex items-center gap-2">
            <span className="size-2.5 rounded-sm" style={{ backgroundColor: DONUT_COLORS[i % DONUT_COLORS.length] }} />
            <span className="text-foreground/80">{d.label}</span>
            <span className="tabular-nums text-muted-foreground">{Math.round((d.value / total) * 100)}%</span>
          </li>
        ))}
      </ul>
    </div>
  );
}

src/components/expenses/expense-workspac:
"use client";
import { nativeFieldClassName } from "@/components/ui/input";
import { nativeButtonClassName, nativePrimaryButtonClassName } from "@/components/ui/button";
import Link from "next/link";
import { PageHeader } from "@/components/cafe/ui";
import { useEffect, useState, type FormEvent } from "react";
import { api, ApiRequestError, money } from "@/lib/client";
import { useApp } from "@/components/app-shell";
import { Dialog, DialogContent, DialogTitle } from "@/components/ui/dialog";
import { expenseInput, returnInput, categoryInput, mayExecuteExpense } from "@/lib/expense-rules";
import { beginExpenseIntent, loadExpenseIntent, completeExpenseIntent, type ExpenseIntent } from "@/lib/expense-intent";
import type { expenseDto } from "@/lib/expenses";

type Expense = ReturnType<typeof expenseDto>;
type Category = { id: string; code: string; nameAr: string; archivedAt: string | null };
type Metadata = { categories: Category[]; branches: { id: string; name: string }[] };
type Listing = { expenses: Expense[]; count: number; pageSize: number; totals: { paid: number; returned: number } };
const field = nativeFieldClassName;
const button = nativeButtonClassName;
const message = (error: unknown) => error instanceof Error ? error.message : "تعذر إكمال الطلب";
const uncertainResult = (error: unknown) => !(error instanceof ApiRequestError) || error.status >= 500 || error.status === 409;
const date = (iso: string) => new Date(iso).toLocaleString("ar-EG", { timeZone: "Africa/Cairo" });

export function ExpenseWorkspace() {
  const { user, canKey, permKeys } = useApp();
  const view = canKey("expenses.view");
  const intentOwner = (user.cafeId ?? "") + ":" + user.id;
  const [pending, setPending] = useState<ExpenseIntent | null>(null);
  const [readyOwner, setReadyOwner] = useState("");
  const intentReady = readyOwner === intentOwner;
  const manage = mayExecuteExpense(user.role, new Set(permKeys));
  const [metadata, setMetadata] = useState<Metadata>({ categories: [], branches: [] });
  const [setupError, setSetupError] = useState("");
  const [branchId, setBranchId] = useState(user.branchId ?? "");
  const [categoryId, setCategoryId] = useState("");
  const [search, setSearch] = useState(""); const [filterCategory, setFilterCategory] = useState("");
  const [amount, setAmount] = useState("");
  const [description, setDescription] = useState("");
  const [reference, setReference] = useState("");
  const [from, setFrom] = useState(""); const [to, setTo] = useState("");
  const [page, setPage] = useState(1); const [version, setVersion] = useState(0);
  const [listing, setListing] = useState<Listing | null>(null);
  const [loading, setLoading] = useState(true); const [readError, setReadError] = useState("");
  const [error, setError] = useState(""); const [success, setSuccess] = useState("");
  const [busy, setBusy] = useState(false); const [uncertain, setUncertain] = useState(false);
  const [categoryName, setCategoryName] = useState(""); const [categoryCode, setCategoryCode] = useState("");
  const [categoryBusy, setCategoryBusy] = useState(false); const [categoryError, setCategoryError] = useState("");
  const [createOpen, setCreateOpen] = useState(false); const [categoriesOpen, setCategoriesOpen] = useState(false);
  useEffect(() => {
    let live = true;
    Promise.resolve().then(() => loadExpenseIntent(window.sessionStorage, intentOwner, "/api/expenses"))
      .then(intent => {
        if (!live) return;
        setPending(intent); setUncertain(!!intent);
        if (intent && "branchId" in intent.body) {
          setBranchId(intent.body.branchId); setCategoryId(intent.body.categoryId); setAmount(String(intent.body.amount));
          setDescription(intent.body.description); setReference(intent.body.documentReference ?? "");
        }
        setReadyOwner(intentOwner);
      }).catch(e => { if (live) setError(message(e)); });
    return () => { live = false; };
  }, [intentOwner]);
  useEffect(() => {
    if (!view) return;
    let live = true;
    const controller = new AbortController();
    api<Metadata>("/api/expenses/categories", {signal:controller.signal,readTimeoutMs:20_000})
      .then(r => { if (live) { setMetadata(r); setSetupError(""); } })
      .catch(e => { if (live) setSetupError(message(e)); });
    return () => { live = false; controller.abort(); };
  }, [view, version]);
  useEffect(() => {
    if (!view) return;
    let live = true;
    const q = new URLSearchParams({ page: String(page), ...(search ? { q: search } : {}), ...(filterCategory ? { categoryId: filterCategory } : {}), ...(branchId ? { branchId } : {}), ...(from ? { from } : {}), ...(to ? { to } : {}) });
    const controller = new AbortController();
    api<Listing>(`/api/expenses?${q}`, {signal:controller.signal,readTimeoutMs:20_000})
      .then(r => { if (live) { setListing(r); setReadError(""); } })
      .catch(e => { if (live) { setReadError(message(e)); setListing(null); } })
      .finally(() => { if (live) setLoading(false); });
    return () => { live = false; controller.abort(); };
  }, [branchId, from, to, page, version, view, search, filterCategory]);
  function refresh() { setLoading(true); setVersion(v => v + 1); }
  async function pay(event: FormEvent) {
    event.preventDefault(); if (!intentReady) return;
    setError(""); setSuccess("");
    const result = pending ? null : expenseInput.safeParse({ branchId, categoryId, amount: Number(amount), description, ...(reference.trim() ? { documentReference: reference } : {}) });
    if (result && !result.success) { setError(result.error.issues.map(i => i.message).join("؛ ")); return; }
    setBusy(true);
    let intent = pending;
    try {
      intent ??= beginExpenseIntent(window.sessionStorage, intentOwner, "/api/expenses", result?.data);
      setPending(intent);
      const saved = await api<Expense>(intent.path, { method: "POST", body: intent.body, idempotencyKey: intent.key });
      if (!completeExpenseIntent(window.sessionStorage, intentOwner, intent)) throw new Error("هوية الطلب المعلّق اتغيرت؛ راجع نتيجته قبل حركة جديدة");
      setPending(null); setUncertain(false); setAmount(""); setDescription(""); setReference(""); setSuccess(saved.id); refresh();
    } catch (e) {
      let keep = !!pending || uncertainResult(e);
      if (intent && !keep) { try { completeExpenseIntent(window.sessionStorage, intentOwner, intent); } catch { keep = true; } }
      setPending(keep ? intent : null); setUncertain(keep && !!intent); setError(message(e));
    } finally { setBusy(false); }
  }
  async function createCategory(event: FormEvent) {
    event.preventDefault(); setCategoryError("");
    const result = categoryInput.safeParse({ code: categoryCode, nameAr: categoryName, classification: "OPERATING_EXPENSE" });
    if (!result.success) { setCategoryError(result.error.issues.map(i => i.message).join("؛ ")); return; }
    setCategoryBusy(true);
    try { await api("/api/expenses/categories", { method: "POST", body: result.data }); setCategoryName(""); setCategoryCode(""); refresh(); }
    catch (e) { setCategoryError(message(e)); } finally { setCategoryBusy(false); }
  }
  async function archive(c: Category) {
    setCategoryError(""); setCategoryBusy(true);
    try { await api(`/api/expenses/categories/${c.id}`, { method: "PATCH", body: { archived: !c.archivedAt } }); refresh(); }
    catch (e) { setCategoryError(message(e)); } finally { setCategoryBusy(false); }
  }
  if (!view) return <p role="alert">ليس لديك صلاحية عرض المصروفات.</p>;
  return <main dir="rtl" className="workspace-page">
    <PageHeader title="المصروفات التشغيلية" subtitle="سجل المصروفات وردود النقد من درج الوردية" />
    <div className="flex flex-wrap items-center gap-3"><Link href="/finance" className="text-primary underline">مساحة الماليات ←</Link>{manage && <button className={nativePrimaryButtonClassName} onClick={() => setCreateOpen(true)}>{uncertain ? "استعادة نتيجة المصروف المعلق" : "+ إضافة مصروف"}</button>}{user.role === "CAFE_OWNER" && manage && <button className={button} onClick={() => setCategoriesOpen(true)}>تصنيفات المصروفات</button>}</div>
    <p>مصروف تشغيلي مدفوع فورًا من درجك الحالي بالجنيه المصري. المشتريات وسداد الموردين والسلف والأجور والأصول ومسحوبات المالك لها مسارات منفصلة.</p>
    <div className="workspace-toolbar"><label>بحث في المصروفات<input className={field} maxLength={120} value={search} onChange={e => { setSearch(e.target.value); setPage(1); setLoading(true); }} /></label><label>التصنيف<select className={field} value={filterCategory} onChange={e => { setFilterCategory(e.target.value); setPage(1); setLoading(true); }}><option value="">كل التصنيفات</option>{metadata.categories.map(c => <option key={c.id} value={c.id}>{c.nameAr}{c.archivedAt ? " — مؤرشف" : ""}</option>)}</select></label></div>
    <div className="grid gap-3 rounded-xl bg-card p-4 sm:grid-cols-3">
      <div><label htmlFor="expense-branch">الفرع</label><select id="expense-branch" className={field} value={branchId} disabled={!!user.branchId || busy || uncertain || !intentReady} onChange={e => { setBranchId(e.target.value); setPage(1); setLoading(true); }}>
        <option value="">كل الفروع — اختر فرعًا للصرف</option>{metadata.branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}
      </select></div>
      <div><label htmlFor="expense-from">من تاريخ — القاهرة</label><input id="expense-from" className={field} type="date" value={from} onChange={e => { setFrom(e.target.value); setPage(1); setLoading(true); }} /></div>
      <div><label htmlFor="expense-to">إلى تاريخ — القاهرة</label><input id="expense-to" className={field} type="date" value={to} onChange={e => { setTo(e.target.value); setPage(1); setLoading(true); }} /></div>
    </div>
    {setupError && <p role="alert">تعذر تحميل الفروع والتصنيفات: {setupError} <button className={button} onClick={refresh}>إعادة التحميل</button></p>}
    {manage && <Dialog open={createOpen} onOpenChange={setCreateOpen}><DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-2xl"><DialogTitle>إضافة مصروف تشغيلي</DialogTitle><form onSubmit={pay} className="space-y-3 rounded-xl border p-4" aria-label="تسجيل مصروف">
      <h2 className="text-lg font-semibold">تسجيل مصروف من الدرج</h2>
      <fieldset disabled={busy || uncertain || !intentReady} className="grid gap-3 sm:grid-cols-2">
        <div className="sm:col-span-2"><label htmlFor="expense-create-branch">فرع المصروف</label><select id="expense-create-branch" className={field} value={branchId} disabled={!!user.branchId || busy || uncertain || !intentReady} required onChange={e => setBranchId(e.target.value)}><option value="">اختر الفرع الذي سيتم الصرف من درجه</option>{metadata.branches.map(b => <option key={b.id} value={b.id}>{b.name}</option>)}</select>{!branchId && <p className="mt-1 text-sm text-muted-foreground">اختيار الفرع مطلوب لتحديد درج الصرف الحالي.</p>}</div>
        <div><label htmlFor="expense-category">بند المصروف المعتمد</label><select id="expense-category" className={field} value={categoryId} onChange={e => setCategoryId(e.target.value)} required>
          <option value="">اختر البند</option>{metadata.categories.filter(c => !c.archivedAt || (!!pending && c.id === categoryId)).map(c => <option key={c.id} value={c.id}>{c.nameAr}</option>)}
        </select></div>
        <div><label htmlFor="expense-amount">المبلغ — ج.م</label><input id="expense-amount" className={field} type="number" inputMode="decimal" min="0.01" step="0.01" max="9999999999.99" value={amount} onChange={e => setAmount(e.target.value)} required /></div>
        <div className="sm:col-span-2"><label htmlFor="expense-description">الوصف</label><textarea id="expense-description" className={field} maxLength={500} value={description} onChange={e => setDescription(e.target.value)} required /></div>
        <div className="sm:col-span-2"><label htmlFor="expense-reference">مرجع المستند — اختياري</label><input id="expense-reference" className={field} maxLength={200} value={reference} onChange={e => setReference(e.target.value)} /></div>
      </fieldset>
      {!setupError && !metadata.categories.some(c => !c.archivedAt) && <p>لا توجد تصنيفات متاحة. ينشئ المالك بند مصروف تشغيلي أولًا.</p>}
      {error && <p role="alert">{error}</p>}
      {uncertain && <p role="status">يوجد طلب صرف سابق لم تُحسم نتيجته. استعد النتيجة بنفس البيانات والمفتاح، ولا تسلّم نقدًا جديدًا أثناء الاستعادة.</p>}
      <button className={button} disabled={busy || !intentReady || (!pending && (!branchId || !categoryId || !!setupError))} type="submit">{busy ? "جارٍ التحقق والحفظ…" : uncertain ? "إعادة المحاولة واستعادة النتيجة" : "تسجيل الصرف الفعلي"}</button>
      {success && <p role="status">تم حفظ أو استعادة نتيجة الطلب. <Link className="underline" href={`/expenses/${success}`}>فتح الإيصال ورد النقد</Link></p>}
    </form></DialogContent></Dialog>}
    {readError && <p role="alert">{readError} <button className={button} onClick={refresh}>إعادة التحميل</button></p>}
    {loading ? <p role="status">جارٍ تحميل المصروفات…</p> : listing && <section aria-label="سجل المصروفات" className="space-y-3">
      <p>إجمالي المصروفات في النطاق: {money(listing.totals.paid, "EGP")}؛ النقد المردود لهذه المصروفات: {money(listing.totals.returned, "EGP")}.</p>
      {listing.expenses.length === 0 ? <p>لا توجد مصروفات في النطاق المحدد.</p> : <ul className="space-y-2">{listing.expenses.map(e => <li key={e.id} className="flex flex-wrap items-center justify-between gap-3 border-b border-border bg-card p-4">
        <Link className="font-semibold underline" href={`/expenses/${e.id}`}>{e.categoryName} — {money(e.amount, "EGP")}</Link><p>{e.description}</p><p className="text-sm">{date(e.occurredAt)} — {e.actorName}؛ مردود {money(e.returnedAmount, "EGP")}</p>
      </li>)}</ul>}
      <div className="flex items-center gap-3"><button className={button} disabled={page === 1} onClick={() => { setPage(p => p - 1); setLoading(true); }}>السابق</button><span>صفحة {page}</span><button className={button} disabled={page * listing.pageSize >= listing.count} onClick={() => { setPage(p => p + 1); setLoading(true); }}>التالي</button></div>
    </section>}
    {user.role === "CAFE_OWNER" && manage && <Dialog open={categoriesOpen} onOpenChange={setCategoriesOpen}><DialogContent className="max-h-[90dvh] overflow-y-auto sm:max-w-2xl"><DialogTitle>تصنيفات المصروفات</DialogTitle><section className="space-y-3 rounded-xl border p-4" aria-label="تصنيفات المصروفات">
      <h2 className="text-lg font-semibold">تصنيفات المصروفات — المالك</h2>
      <form onSubmit={createCategory} className="space-y-3">
        <label htmlFor="category-code">كود البند</label><input id="category-code" className={field} dir="ltr" maxLength={40} pattern="[A-Z0-9_]+" value={categoryCode} onChange={e => setCategoryCode(e.target.value)} required />
        <label htmlFor="category-name">اسم البند بالعربية</label><input id="category-name" className={field} maxLength={100} value={categoryName} onChange={e => setCategoryName(e.target.value)} required />
        <label className="flex gap-2"><input type="checkbox" required />أعتمد هذا البند للمصروف التشغيلي فقط، ولا يشمل مشتريات المخزون أو الموردين أو السلف أو الأجور أو الأصول أو المسحوبات.</label>
        <button className={button} disabled={categoryBusy}>إنشاء التصنيف</button>
      </form>
      {categoryError && <p role="alert">{categoryError}</p>}
      <ul className="space-y-2">{metadata.categories.map(c => <li key={c.id} className="flex flex-wrap items-center gap-3"><span>{c.nameAr}{c.archivedAt ? " — مؤرشف" : ""}</span><button className={button} disabled={categoryBusy} onClick={() => archive(c)}>{c.archivedAt ? "إتاحة البند" : "أرشفة البند"}</button></li>)}</ul>
    </section></DialogContent></Dialog>}
  </main>;
}

export function ExpenseDetail({ id }: { id: string }) {
  const { user, permKeys, canKey } = useApp();
  const view = canKey("expenses.view");
  const intentOwner = (user.cafeId ?? "") + ":" + user.id;
  const intentPath = "/api/expenses/" + id + "/returns";
  const [pending, setPending] = useState<ExpenseIntent | null>(null);
  const [readyOwner, setReadyOwner] = useState("");
  const intentReady = readyOwner === intentOwner;
  const [data, setData] = useState<{ expense: Expense; drawerStatus: string } | null>(null);
  const [version, setVersion] = useState(0); const [error, setError] = useState(""); const [loading, setLoading] = useState(true);
  const [amount, setAmount] = useState(""); const [reason, setReason] = useState(""); const [reference, setReference] = useState("");
  const [busy, setBusy] = useState(false); const [uncertain, setUncertain] = useState(false); const [saved, setSaved] = useState(false);
  useEffect(() => {
    let live = true;
    Promise.resolve().then(() => loadExpenseIntent(window.sessionStorage, intentOwner, intentPath))
      .then(intent => {
        if (!live) return;
        setPending(intent); setUncertain(!!intent);
        if (intent && "reason" in intent.body) { setAmount(String(intent.body.amount)); setReason(intent.body.reason); setReference(intent.body.documentReference ?? ""); }
        setReadyOwner(intentOwner);
      }).catch(e => { if (live) setError(message(e)); });
    return () => { live = false; };
  }, [intentOwner, intentPath]);
  useEffect(() => {
    if (!view) return;
    let live = true;
    const controller = new AbortController();
    api<{ expense: Expense; drawerStatus: string }>(`/api/expenses/${id}`, {signal:controller.signal,readTimeoutMs:20_000})
      .then(r => { if (live) { setData(r); setError(""); } })
      .catch(e => { if (live) setError(message(e)); })
      .finally(() => { if (live) setLoading(false); });
    return () => { live = false; controller.abort(); };
  }, [id, version, view]);
  async function receive(event: FormEvent) {
    event.preventDefault(); if (!intentReady) return;
    setSaved(false); setError("");
    const result = pending ? null : returnInput.safeParse({ amount: Number(amount), reason, ...(reference.trim() ? { documentReference: reference } : {}) });
    if (result && !result.success) { setError(result.error.issues.map(i => i.message).join("؛ ")); return; }
    setBusy(true);
    let intent = pending;
    try {
      intent ??= beginExpenseIntent(window.sessionStorage, intentOwner, intentPath, result?.data);
      setPending(intent);
      const expense = await api<Expense>(intent.path, { method: "POST", body: intent.body, idempotencyKey: intent.key });
      if (!completeExpenseIntent(window.sessionStorage, intentOwner, intent)) throw new Error("هوية الطلب المعلّق اتغيرت؛ راجع نتيجته قبل حركة جديدة");
      setData(d => d ? { ...d, expense } : d); setPending(null); setUncertain(false); setSaved(true); setAmount(""); setReason(""); setReference("");
    } catch (e) {
      let keep = !!pending || uncertainResult(e);
      if (intent && !keep) { try { completeExpenseIntent(window.sessionStorage, intentOwner, intent); } catch { keep = true; } }
      setPending(keep ? intent : null); setUncertain(keep && !!intent); setError(message(e));
    } finally { setBusy(false); }
  }
  if (!view) return <p role="alert">ليس لديك صلاحية عرض المصروف.</p>;
  return <main dir="rtl" className="mx-auto max-w-3xl space-y-4">
    <style>{`@media print { .expense-no-print { display: none !important; } }`}</style>
    <Link href="/expenses" className="expense-no-print underline">العودة للمصروفات</Link><h1 className="text-2xl font-bold">إيصال مصروف ورد النقد</h1>
    {loading && <p role="status">جارٍ تحميل الإيصال…</p>}
    {error && <p role="alert">{error}</p>}
    {!data && !loading && <button className={button} onClick={() => { setLoading(true); setVersion(v => v + 1); }}>إعادة التحميل</button>}
    {data && <>
      <article className="space-y-3 rounded-xl border p-4" aria-label="إيصال المصروف">
        <h2 className="text-xl font-semibold">{data.expense.categoryName} — {money(data.expense.amount, "EGP")}</h2>
        <p>مصروف تشغيلي مدفوع من الدرج — {data.expense.currency}</p><p>{data.expense.description}</p>
        <dl className="space-y-2">
          <div><dt>رقم المصروف</dt><dd className="break-all">{data.expense.id}</dd></div>
          <div><dt>الفرع / الوردية الأصلية</dt><dd className="break-all">{data.expense.branchId} / {data.expense.shiftId}</dd></div>
          <div><dt>المنفذ ووقت الصرف — القاهرة</dt><dd>{data.expense.actorName} — {date(data.expense.occurredAt)}</dd></div>
          <div><dt>مرجع المستند</dt><dd>{data.expense.documentReference ?? "لا يوجد"}</dd></div>
          <div><dt>النقد المردود / المتبقي غير المردود</dt><dd>{money(data.expense.returnedAmount, "EGP")} / {money(data.expense.unrecoveredAmount, "EGP")}</dd></div>
        </dl>
        <h3 className="font-semibold">ردود نقدية موثقة</h3>
        {data.expense.returns.length === 0 ? <p>لم يُسجل رد نقد.</p> : <ul className="space-y-2">{data.expense.returns.map(r => <li key={r.id} className="rounded-lg border p-2">
          {money(r.amount, "EGP")} — {r.reason}<p>{r.actorName} — {date(r.occurredAt)}</p><p>مرجع: {r.documentReference ?? "لا يوجد"}</p>
        </li>)}</ul>}
        <button className={button + " expense-no-print"} onClick={() => window.print()}>طباعة الإيصال</button>
      </article>
      {mayExecuteExpense(user.role, new Set(permKeys)) && (pending || data.expense.unrecoveredAmount > 0) && <section className="expense-no-print rounded-xl border p-4">
        <h2 className="text-lg font-semibold">تسجيل عودة نقد فعلية</h2>
        <p>لا يمحو المصروف. يُقبل فقط إلى الدرج الأصلي وهو مفتوح وفي عهدتك. الرد إلى درج آخر أو بعد الإقفال يحتاج مسارًا منفصلًا.</p>
        {data.drawerStatus !== "OPEN" && !pending ? <p role="status">الدرج الأصلي مغلق أو قيد التسليم؛ الرد غير متاح في هذه الدفعة.</p> : <form onSubmit={receive} className="space-y-3">
          <fieldset disabled={busy || uncertain || !intentReady} className="space-y-2">
            <label htmlFor="return-amount">النقد الذي عاد — ج.م</label><input id="return-amount" className={field} type="number" inputMode="decimal" min="0.01" step="0.01" max={data.expense.unrecoveredAmount} value={amount} onChange={e => setAmount(e.target.value)} required />
            <label htmlFor="return-reason">سبب ودليل عودة النقد</label><textarea id="return-reason" className={field} maxLength={500} value={reason} onChange={e => setReason(e.target.value)} required />
            <label htmlFor="return-reference">مرجع المستند — اختياري</label><input id="return-reference" className={field} maxLength={200} value={reference} onChange={e => setReference(e.target.value)} />
            <label className="flex gap-2"><input type="checkbox" required />أؤكد استلام النقد فعليًا في الدرج الأصلي.</label>
          </fieldset>
          {uncertain && <p role="status">يوجد طلب رد سابق لم تُحسم نتيجته. استعد نتيجته؛ لا تستلم نقدًا جديدًا أثناء الاستعادة.</p>}
          <button className={button} disabled={busy || !intentReady}>{busy ? "جارٍ الحفظ…" : uncertain ? "إعادة المحاولة بنفس الطلب" : "تسجيل النقد المستلم"}</button>
        </form>}
      </section>}
      {saved && <p role="status">تم تسجيل عودة النقد وحفظ دليلها.</p>}
    </>}
  </main>;
}

src/components/pos/category-tabs.tsx:
"use client";

import { useId, useState } from "react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import { categoryIcon, type Category } from "./types";

export function CategoryTabs({
  categories,
  active,
  counts,
  onChange,
}: {
  categories: Category[];
  active: string; // "all" or category id
  counts: Map<string, number>; // category id → product count
  onChange: (id: string) => void;
}) {
  const choices = [{ id: "all", name: "كل المنتجات" }, ...categories];
  const pageSize = 3;
  const activePage = Math.max(0, Math.floor(choices.findIndex(c => c.id === active) / pageSize));
  const [navigation, setNavigation] = useState(() => ({active, page: activePage}));
  const page = navigation.active === active ? navigation.page : activePage;
  function setPage(page: number) { setNavigation({active,page}); }
  const [panelOpen, setPanelOpen] = useState(false);
  const dialogId = useId();
  const [query, setQuery] = useState("");
  const pages = Math.ceil(choices.length / pageSize);
  const currentPage = Math.min(page, pages - 1);
  const selected = choices.find(c => c.id === active)?.name ?? "التصنيف غير متاح — اختر تصنيفًا";
  function choose(id: string) {
    onChange(id);
    setPage(Math.max(0, Math.floor(choices.findIndex(c => c.id === id) / pageSize)));
    setPanelOpen(false);
  }
  const tab = (id: string, label: string, icon?: string) => (
    <button
      key={id}
      type="button"
      aria-pressed={active === id}
      onClick={() => choose(id)}
      className={cn(
        "category-choice flex min-h-12 min-w-28 items-center gap-2 rounded-xl border px-3 py-2 text-start text-sm font-semibold transition-colors",
        active === id
          ? "border-primary bg-primary text-primary-foreground"
          : "bg-card hover:bg-accent"
      )}
    >
      {icon && <span aria-hidden="true">{icon}</span>}
      <span className="min-w-0 flex-1 whitespace-normal [overflow-wrap:normal]">{label}{active === id && <span className="block text-xs">✓ محدد</span>}</span>
      {counts.has(id) && (
        <span
          className={cn(
            "shrink-0 rounded-full px-1.5 text-xs tabular-nums",
            active === id ? "bg-primary-foreground/20" : "bg-muted"
          )}
        >
          {counts.get(id)}
        </span>
      )}
    </button>
  );

  return (
    <Dialog open={panelOpen} onOpenChange={setPanelOpen}>
    <section aria-label="تصنيفات المنتجات" className="cashier-categories shrink-0 space-y-2 rounded-xl bg-card p-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <p className="w-full min-w-0 text-xs text-muted-foreground sm:w-auto sm:flex-1">التصنيف المحدد: <strong>{selected}</strong></p>
        <Button className="category-all-products" variant="outline" aria-pressed={active === "all"} onClick={() => choose("all")}>كل المنتجات{active === "all" && " ✓ محدد"}</Button>
        {categories.length > 0 && <DialogTrigger render={<Button variant="outline" aria-controls={dialogId} />} onClick={() => setQuery("")}>كل التصنيفات ({categories.length})</DialogTrigger>}
      </div>
      <div className="category-pages grid grid-cols-2 gap-2 sm:grid-cols-3">{choices.slice(currentPage * pageSize, (currentPage + 1) * pageSize).map(c => tab(c.id,c.name,c.id === "all" ? "▦" : categoryIcon(c.name)))}</div>
      {pages > 1 && <div className="category-navigation flex items-center justify-between gap-2" aria-label="صفحات التصنيفات">
        <Button variant="outline" aria-label="التصنيفات السابقة" disabled={currentPage === 0} onClick={() => setPage(currentPage - 1)}>السابق</Button>
        <span role="status" className="text-sm">{currentPage + 1} / {pages}</span>
        <Button variant="outline" aria-label="التصنيفات التالية" disabled={currentPage === pages - 1} onClick={() => setPage(currentPage + 1)}>التالي</Button>
      </div>}
        <DialogContent id={dialogId} className="sm:max-w-2xl" dir="rtl">
          <DialogHeader><DialogTitle>كل التصنيفات — اختر تصنيفًا</DialogTitle></DialogHeader>
          <Input aria-label="البحث في التصنيفات" placeholder="اسم التصنيف بالعربية أو الإنجليزية" value={query} onChange={e => setQuery(e.target.value)} />
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">{choices.filter(c => c.name.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())).map(c => tab(c.id,c.name,categoryIcon(c.name)))}</div>
          {!choices.some(c => c.name.toLocaleLowerCase().includes(query.trim().toLocaleLowerCase())) && <p role="status">لا توجد تصنيفات بهذا الاسم. غيّر البحث.</p>}
          <DialogFooter><Button variant="outline" onClick={() => setPanelOpen(false)}>رجوع للمنتجات</Button></DialogFooter>
        </DialogContent>
    </section>
    </Dialog>
  );
}

src/components/pos/collect-payment-panel:
"use client";
import { TouchNumberInput } from "@/components/pos/touch-number-input";

import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { api, money } from "@/lib/client";
import { useApp } from "@/components/app-shell";
import { PaymentReceiptPreview } from "@/components/receipts/payment-receipt-preview";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import { cn } from "@/lib/utils";
import { maxRedeemablePoints, pointsValue, type LoyaltyCalcSettings } from "@/lib/loyalty-calc";

type LookupCustomer = {
  id: string;
  name: string | null;
  phone: string;
  loyaltyPointsBalance: number;
  totalOrders: number;
  totalSpent?: number;
  lastOrderAt: string | null;
  isActive: boolean;
};

type OrderTarget = {
  kind: "order";
  orderId: string;
  orderNumber: number;
  branchName: string;
  status: string;
  tableNumber: string | null;
  customerName: string | null;
  total: number;
  paidAmount: number;
  remainingAmount: number;
  paymentStatus: string;
  alreadyRedeemed: boolean;
  customer: LookupCustomer | null;
  payments: { id: string; amount: number; method: string; createdAt: string }[];
};

const METHOD_LABEL: Record<string, string> = { CASH: "كاش", CARD: "فيزا", WALLET: "محفظة" };

function lastVisitLabel(v: string | null): string {
  if (!v) return "لا يوجد";
  const days = Math.floor((Date.now() - new Date(v).getTime()) / 86_400_000);
  if (days <= 0) return "اليوم";
  if (days === 1) return "أمس";
  return `منذ ${days} يوم`;
}

// POS collection mode for a single order (/pos?collectOrderId=…): the one
// place money is collected. Includes the customer/points section — the
// cashier can apply a loyalty discount before collecting the rest.
export function CollectPaymentPanel({
  orderId,
  currency,
  needsShift,
  shiftActive,
  onDone,
  onClose,
}: {
  orderId: string;
  currency: string;
  needsShift: boolean;
  shiftActive: boolean;
  onDone: () => void;
  onClose: () => void;
}) {
  const { canKey, can } = useApp();
  const canRedeem = canKey("loyalty.redeem_points");
  const canServe = can("orders:update-status");
  const [served, setServed] = useState(false);

  const [target, setTarget] = useState<OrderTarget | null>(null);
  const [loyalty, setLoyalty] = useState<LoyaltyCalcSettings | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [amount, setAmount] = useState("");
  const [method, setMethod] = useState<"CASH" | "CARD" | "WALLET">("CASH");
  const [busy, setBusy] = useState(false);
  const inFlight = useRef(false);
  const [collectionError, setCollectionError] = useState<string | null>(null);
  const [receipt, setReceipt] = useState<{ paymentId: string | null; amount: number; loyaltyDiscount: number } | null>(null);

  // بيانات العميل والنقاط
  const [phone, setPhone] = useState("");
  const [customer, setCustomer] = useState<LookupCustomer | null>(null);
  const [looked, setLooked] = useState(false);
  const [redeem, setRedeemState] = useState<{ points: number; discount: number }>({ points: 0, discount: 0 });
  const [redeemOpen, setRedeemOpen] = useState(false);
  const [pointsInput, setPointsInput] = useState("");
  const [redeemError, setRedeemError] = useState<string | null>(null);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const targetController=useRef<AbortController|null>(null);
  async function loadTarget() {
    targetController.current?.abort();const controller=new AbortController();targetController.current=controller;setError(null);
    const r = await api<{ target: OrderTarget; loyalty: LoyaltyCalcSettings }>(
      `/api/payments/collect-info?orderId=${orderId}`,{signal:controller.signal,readTimeoutMs:20_000}
    );
    if(controller.signal.aborted)throw new DOMException("تم إلغاء القراءة السابقة","AbortError");
    setTarget(r.target);
    setLoyalty(r.loyalty);
    // Linked customer loads automatically — no retyping the phone.
    if (r.target.customer) {
      setCustomer(r.target.customer);
      setLooked(true);
    }
    return r.target;
  }

  useEffect(() => {
    loadTarget()
      .then((t) => setAmount(String(t.remainingAmount)))
      .catch((e) => {if(e?.name!=="AbortError")setError(e instanceof Error ? e.message : "فشل التحميل")});
    return ()=>targetController.current?.abort();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orderId]);

  // Phone lookup (only needed when the order has no linked customer).
  useEffect(() => {
    if (target?.customer) return; // already linked
    setLooked(false);
    setCustomer(null);
    setRedeemState({ points: 0, discount: 0 });
    const digits = phone.replace(/\D/g, "");
    if (digits.length < 10) return;
    if (timer.current) clearTimeout(timer.current);
    const controller=new AbortController();
    timer.current = setTimeout(async () => {
      try {
        const r = await api<{ customer: LookupCustomer | null }>(
          `/api/customers/lookup?phone=${encodeURIComponent(phone)}`,{signal:controller.signal,readTimeoutMs:20_000}
        );
        if(controller.signal.aborted)return;
        setCustomer(r.customer);
        setLooked(true);
      } catch { if(!controller.signal.aborted)setLooked(false); }
    }, 400);
    return () => { controller.abort(); if (timer.current) clearTimeout(timer.current); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phone, target?.customer]);

  const remaining = target?.remainingAmount ?? 0;
  const settled = remaining <= 0.001;
  const shiftBlocked = needsShift && !shiftActive;

  // Redemption caps: balance, min, max% of the invoice, and the remaining.
  const cap = target && loyalty && customer
    ? Math.min(
        maxRedeemablePoints(customer.loyaltyPointsBalance, target.total, loyalty),
        loyalty.pointValueAmount > 0 ? Math.floor(remaining / loyalty.pointValueAmount) : 0
      )
    : 0;
  const showLoyaltyBlock =
    !!target && !!loyalty && loyalty.enabled && canRedeem && !settled && !target.alreadyRedeemed;

  const requiredToCollect = Math.max(Math.round((remaining - redeem.discount) * 100) / 100, 0);

  // Keep the money field synced to "المطلوب تحصيله".
  useEffect(() => {
    if (target) setAmount(String(requiredToCollect));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [redeem.discount, target?.remainingAmount]);

  function applyRedemption() {
    if (!customer || !loyalty) return setRedeemError("يجب اختيار عميل أولًا");
    const pts = Math.floor(Number(pointsInput) || 0);
    if (pts <= 0) return setRedeemError("اكتب عدد النقاط المستخدمة");
    if (pts > customer.loyaltyPointsBalance) return setRedeemError("لا يمكن استخدام نقاط أكثر من رصيد العميل");
    if (pts < loyalty.minPointsToRedeem) return setRedeemError(`أقل عدد نقاط للاستخدام هو ${loyalty.minPointsToRedeem} نقطة`);
    if (pts > cap) return setRedeemError("لا يمكن أن يتجاوز خصم النقاط الحد المسموح");
    setRedeemError(null);
    setRedeemState({ points: pts, discount: pointsValue(pts, loyalty) });
    setRedeemOpen(false);
  }

  const servable = !!target && target.status === "READY" && canServe && !served;

  // Serving is its own request through the ordinary status route, so the
  // café's payment, stock and custody rules decide it. A refusal after a
  // successful collection leaves the money recorded and says so plainly.
  async function serveNow(afterCollect: boolean) {
    if (!target) return;
    try {
      await api(`/api/orders/${target.orderId}/status`, { method: "PATCH", body: { status: "SERVED" } });
      setServed(true);
      toast.success(`الطلب #${target.orderNumber} اتقدم ✅`);
    } catch (e) {
      const reason = e instanceof Error ? e.message : "فشل التقديم";
      toast.error(afterCollect ? `اتحصّل بس متقدمش: ${reason}` : reason);
    }
  }

  async function collect(andServe = false) {
    if (!target || inFlight.current) return;
    const amt = Number(amount) || 0;
    if (amt <= 0 && redeem.points === 0) return toast.error("مبلغ الدفع يجب أن يكون أكبر من صفر");
    if (amt > requiredToCollect + 0.001) return toast.error("مبلغ الدفع أكبر من المطلوب تحصيله");
    inFlight.current = true;
    setCollectionError(null);
    setBusy(true);
    try {
      const body: Record<string, unknown> = { orderId: target.orderId };
      if (amt > 0) { body.amount = amt; body.method = method; }
      if (redeem.points > 0) {
        body.loyaltyPointsToRedeem = redeem.points;
        if (!target.customer && customer) body.customerPhone = customer.phone;
      }
      const r = await api<{ payments: { id: string }[] }>("/api/payments", { method: "POST", body });
      toast.success("تم تحصيل الدفع بنجاح");
      setReceipt({ paymentId: r.payments[0]?.id ?? null, amount: amt, loyaltyDiscount: redeem.discount });
      if (andServe) await serveNow(true);
    } catch (e) {
      const message = e instanceof Error ? e.message : "فشل التحصيل";
      setCollectionError(message);
      toast.error(message);
    } finally {
      inFlight.current = false;
      setBusy(false);
    }
  }

  if (receipt) {
    return <PaymentReceiptPreview
      paymentId={receipt.paymentId}
      scope="order"
      onClose={onDone}
      extraActions={servable ? <Button variant="outline" onClick={() => serveNow(false)}>🍽️ قدّم الطلب دلوقتي</Button> : undefined}
    />;
  }
  return (
    <Dialog open onOpenChange={(o) => !o && !busy && onClose()}>
      <DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-sm">
        <DialogHeader>
          <DialogTitle>
            تحصيل الدفع{target ? ` — طلب #${target.orderNumber}` : ""}
          </DialogTitle>
        </DialogHeader>

        {collectionError && <p role="alert" className="text-destructive">{collectionError} — المبلغ والبيانات محفوظة. إعادة نفس المحاولة لا تسجل دفعة أخرى.</p>}
        {busy && <p role="status">جاري تسجيل الدفع…</p>}
        {error ? (
          <div role="alert" className="space-y-3 text-sm text-destructive"><p>{error}</p><Button variant="outline" onClick={()=>void loadTarget().then(t=>setAmount(String(t.remainingAmount))).catch(e=>{if(e?.name!=="AbortError")setError(e instanceof Error?e.message:"فشل التحميل")})}>إعادة المحاولة</Button></div>
        ) : !target ? (
          <p className="text-sm text-muted-foreground">جاري التحميل…</p>
        ) : (
          <div className="space-y-3">
            {/* الحساب المحدد */}
            <div className="space-y-1 rounded-xl bg-muted/40 p-3 text-sm">
              <p className="text-xs font-semibold text-muted-foreground">الحساب المحدد</p>
              <div className="flex justify-between">
                <span className="text-muted-foreground">إجمالي الحساب</span>
                <span className="tabular-nums font-semibold">{money(target.total, currency)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">المدفوع سابقًا</span>
                <span className="tabular-nums text-emerald-600">{money(target.paidAmount, currency)}</span>
              </div>
              {redeem.discount > 0 && (
                <div className="flex justify-between text-amber-600 dark:text-amber-400">
                  <span>خصم نقاط الولاء ({redeem.points} نقطة)</span>
                  <span className="tabular-nums">−{money(redeem.discount, currency)}</span>
                </div>
              )}
              <div className="flex justify-between text-base font-bold">
                <span>{redeem.discount > 0 ? "المطلوب تحصيله" : "المبلغ المتبقي"}</span>
                <span className="tabular-nums text-amber-600 dark:text-amber-400">
                  {money(requiredToCollect, currency)}
                </span>
              </div>
              {(target.tableNumber || target.customerName) && (
                <p className="pt-0.5 text-[11px] text-muted-foreground">
                  {target.tableNumber ? `ترابيزة ${target.tableNumber}` : ""}
                  {target.tableNumber && target.customerName ? " · " : ""}
                  {target.customerName ?? ""}
                </p>
              )}
            </div>

            {/* ── بيانات العميل والنقاط ── */}
            {!settled && (
              <div className="space-y-1.5 rounded-xl border p-2.5">
                <p className="text-xs font-semibold">بيانات العميل والنقاط</p>
                {!target.customer && (
                  <Input
                    dir="ltr"
                    inputMode="tel"
                    placeholder="رقم موبايل العميل — 01xx xxx xxxx"
                    className="h-10"
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                  />
                )}
                {customer ? (
                  <div className="space-y-1 rounded-lg bg-blue-500/10 px-2.5 py-1.5 text-[11px] leading-snug text-blue-800 dark:text-blue-300">
                    <p className="text-xs font-semibold">عميل موجود{customer.name ? `: ${customer.name}` : ""}</p>
                    <div className="flex flex-wrap gap-x-3 gap-y-0.5">
                      <span>رصيد النقاط: <b className="tabular-nums">{customer.loyaltyPointsBalance}</b> نقطة</span>
                      <span>إجمالي الطلبات: <b className="tabular-nums">{customer.totalOrders}</b></span>
                      <span>آخر زيارة: {lastVisitLabel(customer.lastOrderAt)}</span>
                    </div>
                  </div>
                ) : looked ? (
                  <p className="rounded-lg bg-muted/50 px-2.5 py-1.5 text-[11px] text-muted-foreground">
                    عميل جديد — لا يوجد رصيد نقاط
                  </p>
                ) : null}

                {/* Redemption */}
                {showLoyaltyBlock && customer && (
                  redeem.points > 0 ? (
                    <div className="flex items-center justify-between rounded-md bg-emerald-500/10 px-2 py-1.5 text-xs text-emerald-700 dark:text-emerald-400">
                      <span>
                        النقاط المستخدمة: <b className="tabular-nums">{redeem.points}</b> · الخصم:{" "}
                        <b className="tabular-nums">{money(redeem.discount, currency)}</b>
                      </span>
                      <button
                        type="button"
                        className="text-[11px] font-medium text-red-600 underline"
                        onClick={() => { setRedeemState({ points: 0, discount: 0 }); setPointsInput(""); }}
                      >
                        إلغاء
                      </button>
                    </div>
                  ) : customer.loyaltyPointsBalance <= 0 ? (
                    <Button size="sm" variant="outline" className="h-8 w-full text-xs" disabled>
                      استخدام نقاط الولاء — لا يوجد رصيد نقاط
                    </Button>
                  ) : customer.loyaltyPointsBalance < (loyalty?.minPointsToRedeem ?? 0) ? (
                    <p className="text-[11px] text-muted-foreground">
                      أقل عدد نقاط للاستخدام هو {loyalty!.minPointsToRedeem} نقطة
                    </p>
                  ) : cap <= 0 ? (
                    <p className="text-[11px] text-muted-foreground">لا يوجد رصيد نقاط كافي</p>
                  ) : !redeemOpen ? (
                    <Button
                      size="sm"
                      variant="outline"
                      className="h-8 w-full border-amber-500/60 text-xs font-semibold"
                      onClick={() => { setPointsInput(String(cap)); setRedeemError(null); setRedeemOpen(true); }}
                    >
                      ⭐ استخدام نقاط الولاء
                    </Button>
                  ) : (
                    <div className="space-y-1.5 rounded-lg border border-amber-500/40 bg-amber-500/5 p-2">
                      <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-[11px] text-muted-foreground">
                        <span>رصيد العميل: <b>{customer.loyaltyPointsBalance}</b> نقطة</span>
                        <span>1 نقطة = {money(loyalty!.pointValueAmount, currency)}</span>
                        <span>الأقصى: <b>{cap}</b> نقطة</span>
                      </div>
                      <div className="flex items-center gap-1.5">
                        <TouchNumberInput
                          type="number" dir="ltr" min={0} max={cap} placeholder="عدد النقاط"
                          className="h-9"
                          value={pointsInput}
                          onValueChange={touchValue => { setPointsInput(touchValue); setRedeemError(null); }}
                        />
                        <Button size="sm" className="h-9 shrink-0 px-3 text-xs" onClick={applyRedemption}>
                          تطبيق الخصم
                        </Button>
                        <Button size="sm" variant="ghost" className="h-9 shrink-0 px-2 text-xs" onClick={() => setRedeemOpen(false)}>
                          إلغاء
                        </Button>
                      </div>
                      {Number(pointsInput) > 0 && loyalty && (
                        <p className="text-[11px] text-muted-foreground">
                          قيمة الخصم: {money(pointsValue(Math.floor(Number(pointsInput) || 0), loyalty), currency)} ·
                          المتبقي بعد الخصم: {money(Math.max(remaining - pointsValue(Math.floor(Number(pointsInput) || 0), loyalty), 0), currency)}
                        </p>
                      )}
                      {redeemError && <p className="text-[11px] text-destructive">{redeemError}</p>}
                    </div>
                  )
                )}
                {target.alreadyRedeemed && (
                  <p className="text-[11px] text-muted-foreground">تم استخدام نقاط الولاء لهذا الطلب بالفعل</p>
                )}
              </div>
            )}

            {/* Payment history */}
            {target.payments.length > 0 && (
              <div className="space-y-1">
                <p className="text-xs font-semibold text-muted-foreground">الدفعات السابقة</p>
                <div className="max-h-24 space-y-1 overflow-y-auto">
                  {target.payments.map((p) => (
                    <div key={p.id} className="flex items-center justify-between gap-1.5 rounded-lg border px-2.5 py-1 text-xs">
                      <span>{METHOD_LABEL[p.method] ?? p.method}</span>
                      <span className="text-muted-foreground">
                        {new Date(p.createdAt).toLocaleTimeString("ar-EG", { hour: "2-digit", minute: "2-digit" })}
                      </span>
                      <b className="tabular-nums">{money(p.amount, currency)}</b>
                      <button
                        type="button"
                        title="إعادة طباعة الريسيت"
                        className="text-muted-foreground hover:text-foreground"
                        onClick={() => window.open(`/receipts/payment/${p.id}?print=1&reprint=1&scope=order`, "_blank")}
                      >
                        🖨️
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {settled ? (
              <div className="space-y-2">
                <p className="rounded-lg bg-emerald-500/10 px-3 py-2 text-sm font-medium text-emerald-700 dark:text-emerald-400">
                  تم تحصيل هذا الحساب بالفعل ✅
                </p>
                {servable && (
                  <Button variant="outline" className="h-10 w-full" onClick={() => serveNow(false)}>
                    🍽️ قدّم الطلب دلوقتي
                  </Button>
                )}
              </div>
            ) : shiftBlocked ? (
              <p className="rounded-lg bg-amber-500/10 px-3 py-2 text-sm text-amber-700 dark:text-amber-400">
                لا يمكن تحصيل الدفع بدون شيفت مفتوح — افتح الشيفت من أعلى شاشة الكاشير أولًا.
              </p>
            ) : (
              <>
                <div className="space-y-1.5">
                  <Label>مبلغ التحصيل</Label>
                  <TouchNumberInput
                    type="number" min="0" step="0.01" dir="ltr"
                    value={amount}
                    onValueChange={touchValue => setAmount(touchValue)}
                  />
                </div>
                <div className="space-y-1.5">
                  <Label>طريقة الدفع</Label>
                  <div className="grid grid-cols-3 gap-1.5">
                    {(["CASH", "CARD", "WALLET"] as const).map((m) => (
                      <button
                        key={m}
                        type="button"
                        onClick={() => setMethod(m)}
                        className={cn(
                          "rounded-lg border px-2 py-2 text-sm font-medium",
                          method === m ? "border-foreground bg-foreground text-background" : "border-border"
                        )}
                      >
                        {METHOD_LABEL[m]}
                      </button>
                    ))}
                  </div>
                </div>
              </>
            )}
          </div>
        )}

        {!receipt && (
          <DialogFooter>
            <Button variant="outline" onClick={onClose} disabled={busy}>
              رجوع لإنشاء طلب
            </Button>
            {target && !settled && !shiftBlocked && (
              <Button variant={servable ? "outline" : "default"} onClick={() => collect(false)} disabled={busy}>
                {busy ? "جاري التحصيل…" : "تحصيل الدفع"}
              </Button>
            )}
            {target && !settled && !shiftBlocked && servable && (
              <Button data-testid="collect-and-serve" onClick={() => collect(true)} disabled={busy}>
                {busy ? "جاري…" : "حصّل وقدّم 🍽️"}
              </Button>
            )}
          </DialogFooter>
        )}
      </DialogContent>
    </Dialog>
  );
}

src/components/pos/customer-loyalty.tsx:
"use client";
import { TouchNumberInput } from "@/components/pos/touch-number-input";

import { useEffect, useRef, useState } from "react";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Dialog, DialogContent, DialogFooter, DialogHeader, DialogTitle,
} from "@/components/ui/dialog";
import { api, money } from "@/lib/client";
import { useApp } from "@/components/app-shell";
import {
  maxRedeemablePoints,
  pointsValue,
  type LoyaltyCalcSettings,
} from "@/lib/loyalty-calc";
import type { CollectionMode } from "./types";

export type LoyaltyRedeem = { points: number; discount: number };

type LookupCustomer = {
  id: string;
  name: string | null;
  phone: string;
  loyaltyPointsBalance: number;
  totalOrders: number;
  totalSpent?: number;
  lastOrderAt: string | null;
  isActive: boolean;
};

function lastVisitLabel(v: string | null): string {
  if (!v) return "لا يوجد";
  const days = Math.floor((Date.now() - new Date(v).getTime()) / 86_400_000);
  if (days <= 0) return "اليوم";
  if (days === 1) return "أمس";
  return `منذ ${days} يوم`;
}

// POS customer block: phone field + live lookup (عميل موجود/جديد) + the
// "نقاط الولاء" section with a modal redemption flow. Redemption reports
// {points, discount} up to the POS page, which folds the discount into
// the charge engine. Points can only be redeemed with تحصيل الآن (MVP
// rule — no pending-reservation edge cases).
export function CustomerLoyalty({
  branchId,
  phone,
  customerName,
  orderTotalBeforeLoyalty,
  previewTotalAfterDiscount,
  collectionMode,
  redeem,
  onPhoneChange,
  onRedeemChange,
}: {
  branchId?: string;
  phone: string;
  customerName: string;
  orderTotalBeforeLoyalty: number;
  // Exact post-discount total from the charge engine (loyalty discount
  // applies pre-tax, so total − discount would be wrong).
  previewTotalAfterDiscount: (loyaltyDiscount: number) => number;
  collectionMode: CollectionMode;
  redeem: LoyaltyRedeem;
  onPhoneChange: (phone: string) => void;
  onRedeemChange: (redeem: LoyaltyRedeem) => void;
}) {
  const { cafe, canKey } = useApp();
  const currency = cafe?.currency ?? "EGP";
  const canRedeem = canKey("loyalty.redeem_points");
  const collectNow = collectionMode === "NOW";

  const [customer, setCustomer] = useState<LookupCustomer | null>(null);
  const [loyalty, setLoyalty] = useState<LoyaltyCalcSettings | null>(null);
  const [looked, setLooked] = useState(false); // a lookup finished for current phone
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Redemption modal
  const [modalOpen, setModalOpen] = useState(false);
  const [pointsInput, setPointsInput] = useState("");
  const [modalError, setModalError] = useState<string | null>(null);

  const digits = phone.replace(/\D/g, "");
  const looksComplete = digits.length >= 10;

  // Debounced lookup once the phone looks complete.
  useEffect(() => {
    setLooked(false);
    setCustomer(null);
    if (redeem.points > 0) onRedeemChange({ points: 0, discount: 0 });
    setPointsInput("");
    if (!looksComplete || !branchId) return;
    if (timer.current) clearTimeout(timer.current);
    const controller=new AbortController();
    timer.current = setTimeout(async () => {
      try {
        const r = await api<{ customer: LookupCustomer | null; loyalty: LoyaltyCalcSettings }>(
          `/api/customers/lookup?phone=${encodeURIComponent(phone)}`,{signal:controller.signal,readTimeoutMs:20_000}
        );
        if(controller.signal.aborted)return;
        setCustomer(r.customer);
        setLoyalty(r.loyalty);
        setLooked(true);
      } catch {
        if(controller.signal.aborted)return;
        setLooked(false); // invalid number or no permission — stay quiet
      }
    }, 400);
    return () => { controller.abort(); if (timer.current) clearTimeout(timer.current); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phone, branchId]);

  const cap = customer && loyalty
    ? maxRedeemablePoints(customer.loyaltyPointsBalance, orderTotalBeforeLoyalty, loyalty)
    : 0;

  // Applied redemption must stay valid as the cart or collection mode change.
  useEffect(() => {
    if (redeem.points === 0) return;
    if (!collectNow) {
      onRedeemChange({ points: 0, discount: 0 });
      setPointsInput("");
      return;
    }
    if (loyalty && redeem.points > cap) {
      const pts = Math.max(cap, 0);
      onRedeemChange({ points: pts, discount: pointsValue(pts, loyalty) });
      setPointsInput(pts > 0 ? String(pts) : "");
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [orderTotalBeforeLoyalty, collectNow]);

  function applyFromModal() {
    if (!customer || !loyalty) return;
    const pts = Math.floor(Number(pointsInput) || 0);
    if (pts <= 0) return setModalError("اكتب عدد النقاط المستخدمة");
    if (pts > customer.loyaltyPointsBalance)
      return setModalError("لا يمكن استخدام نقاط أكثر من رصيد العميل");
    if (pts < loyalty.minPointsToRedeem)
      return setModalError(`أقل عدد نقاط للاستخدام هو ${loyalty.minPointsToRedeem} نقطة`);
    if (pts > cap)
      return setModalError(`لا يمكن أن يتجاوز خصم النقاط ${loyalty.maxRedeemPercentageOfOrder}٪ من قيمة الطلب`);
    setModalError(null);
    onRedeemChange({ points: pts, discount: pointsValue(pts, loyalty) });
    setModalOpen(false);
  }

  const modalPts = Math.floor(Number(pointsInput) || 0);
  const modalDiscount = loyalty ? pointsValue(Math.max(modalPts, 0), loyalty) : 0;

  const showLoyaltySection =
    !!customer && !!loyalty && loyalty.enabled && canRedeem && customer.isActive;

  return (
    <div className="space-y-2">
      <p className="text-xs font-medium text-muted-foreground">رقم الموبايل (لبرنامج الولاء)</p>
      <Input
        dir="ltr"
        inputMode="tel"
        placeholder="01xx xxx xxxx"
        value={phone}
        onChange={(e) => onPhoneChange(e.target.value)}
      />

      {/* Lookup result */}
      {looksComplete && looked && (
        customer ? (
          <div className="space-y-1 rounded-lg border border-tide-line bg-tide-soft px-2.5 py-2 text-[11px] leading-snug text-tide-ink">
            <p className="text-xs font-semibold">
              عميل موجود{customer.name ? `: ${customer.name}` : ""}
              {!customer.isActive && <span className="ms-1 text-clay-ink"> (معطّل)</span>}
            </p>
            <div className="flex flex-wrap gap-x-3 gap-y-0.5">
              <span>رصيد النقاط: <b className="tabular-nums">{customer.loyaltyPointsBalance}</b> نقطة</span>
              <span>إجمالي الطلبات: <b className="tabular-nums">{customer.totalOrders}</b></span>
              <span>آخر زيارة: {lastVisitLabel(customer.lastOrderAt)}</span>
            </div>
          </div>
        ) : (
          <p className="rounded-lg border border-sage-line bg-sage-soft px-2.5 py-1.5 text-[11px] text-sage-ink">
            عميل جديد — سيتم إنشاء حساب له بعد تسجيل الطلب
            {customerName.trim() ? ` باسم ${customerName.trim()}` : ""}.
          </p>
        )
      )}

      {/* ── نقاط الولاء ── */}
      {showLoyaltySection && (
        <div className="space-y-1.5 rounded-lg border border-caramel-line bg-caramel-soft p-2">
          <p className="text-xs font-semibold">نقاط الولاء</p>
          <div className="flex flex-wrap gap-x-3 gap-y-0.5 text-[11px] text-muted-foreground">
            <span>رصيد النقاط الحالي: <b className="tabular-nums text-foreground">{customer!.loyaltyPointsBalance}</b></span>
            <span>قيمة الخصم المتاحة: <b className="tabular-nums text-foreground">{money(pointsValue(cap, loyalty!), currency)}</b></span>
          </div>

          {redeem.points > 0 ? (
            <div className="flex items-center justify-between rounded-md border border-sage-line bg-sage-soft px-2 py-1.5 text-xs text-sage-ink">
              <span>
                النقاط المستخدمة: <b className="tabular-nums">{redeem.points}</b> · خصم النقاط:{" "}
                <b className="tabular-nums">{money(redeem.discount, currency)}</b>
              </span>
              <button
                type="button"
                className="text-[11px] font-medium text-clay-ink underline"
                onClick={() => { onRedeemChange({ points: 0, discount: 0 }); setPointsInput(""); }}
              >
                إلغاء
              </button>
            </div>
          ) : !collectNow ? (
            <p className="text-[11px] text-caramel-ink">
              يمكن استخدام النقاط عند التحصيل الآن فقط
            </p>
          ) : customer!.loyaltyPointsBalance <= 0 ? (
            <Button size="sm" variant="outline" className="h-8 w-full text-xs" disabled>
              استخدام نقاط الولاء — لا يوجد رصيد نقاط
            </Button>
          ) : customer!.loyaltyPointsBalance < loyalty!.minPointsToRedeem ? (
            <p className="text-[11px] text-muted-foreground">
              أقل عدد نقاط للاستخدام هو {loyalty!.minPointsToRedeem} نقطة
            </p>
          ) : cap <= 0 ? (
            <p className="text-[11px] text-muted-foreground">لا يوجد رصيد نقاط كافي</p>
          ) : (
            <Button
              size="sm"
              variant="outline"
              className="h-8 w-full border-caramel-line text-xs font-semibold"
              onClick={() => {
                if (!phone.trim()) return; // guarded by section visibility anyway
                setPointsInput(String(cap));
                setModalError(null);
                setModalOpen(true);
              }}
            >
              ⭐ استخدام نقاط الولاء
            </Button>
          )}
        </div>
      )}

      {/* ── Redemption modal ── */}
      <Dialog open={modalOpen} onOpenChange={(o) => !o && setModalOpen(false)}>
        <DialogContent className="max-w-xs">
          <DialogHeader>
            <DialogTitle>استخدام نقاط الولاء</DialogTitle>
          </DialogHeader>
          {customer && loyalty && (
            <div className="space-y-3 text-sm">
              <div className="space-y-1 rounded-lg bg-muted/40 p-2.5 text-xs">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">رصيد العميل</span>
                  <span className="tabular-nums font-semibold">{customer.loyaltyPointsBalance} نقطة</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">قيمة النقطة</span>
                  <span className="tabular-nums">1 نقطة = {money(loyalty.pointValueAmount, currency)}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-muted-foreground">إجمالي الفاتورة</span>
                  <span className="tabular-nums">{money(orderTotalBeforeLoyalty, currency)}</span>
                </div>
              </div>
              <div className="space-y-1.5">
                <Label>عدد النقاط المستخدمة (الأقصى {cap})</Label>
                <TouchNumberInput
                  type="number" dir="ltr" min={0} max={cap}
                  value={pointsInput}
                  onValueChange={touchValue => { setPointsInput(touchValue); setModalError(null); }}
                />
              </div>
              <div className="space-y-1 text-xs">
                <div className="flex justify-between">
                  <span className="text-muted-foreground">قيمة الخصم</span>
                  <span className="tabular-nums font-semibold text-sage-ink">
                    −{money(modalDiscount, currency)}
                  </span>
                </div>
                <div className="flex justify-between font-semibold">
                  <span>المتبقي بعد الخصم</span>
                  <span className="tabular-nums">
                    {money(Math.max(previewTotalAfterDiscount(modalDiscount), 0), currency)}
                  </span>
                </div>
              </div>
              {modalError && <p className="text-xs text-destructive">{modalError}</p>}
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalOpen(false)}>إلغاء</Button>
            <Button onClick={applyFromModal}>تطبيق الخصم</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

src/components/pos/order-cart.tsx:
"use client";
import type {ReactNode, Ref} from 'react';

import { Badge } from "@/components/ui/badge";
import { t } from "@/lib/i18n";
import { CartItem } from "./cart-item";
import {
  OrderTypeSelector,
  type CustomerDetails,
} from "./order-type-selector";
import { PaymentSummary, type MixedAmounts } from "./payment-summary";
import { CustomerLoyalty, type LoyaltyRedeem } from "./customer-loyalty";
import type { CartLine, CollectionMode, OrderType, PaymentMethod, SplitMethod } from "./types";

export function OrderCart({
  id,
  headingId,
  headingRef,
  discountControls,
  cart,
  currency,
  orderType,
  details,
  branchId,
  tableReloadKey,
  totalBeforeLoyalty,
  previewTotalAfterDiscount,
  redeem,
  onRedeemChange,
  subtotal,
  discountInput,
  discountError = null,
  discountAmount,
  serviceCharge,
  taxRate,
  taxAmount,
  total,
  collectionMode,
  paidInput,
  method,
  mixed,
  placeDisabled,
  disabledReason,
  submitting,
  onTypeChange,
  onDetailsChange,
  onQuantityChange,
  onRemove,
  onNoteChange,
  onDiscountChange,
  onCollectionModeChange,
  onPaidChange,
  onMethodChange,
  onMixedChange,
  onPlaceOrder,
}: {
  id?: string;
  headingId?: string;
  headingRef?: Ref<HTMLHeadingElement>;
  discountControls?:ReactNode;
  cart: CartLine[];
  currency: string;
  orderType: OrderType;
  details: CustomerDetails;
  branchId?: string;
  tableReloadKey?: number;
  totalBeforeLoyalty: number;
  previewTotalAfterDiscount: (loyaltyDiscount: number) => number;
  redeem: LoyaltyRedeem;
  onRedeemChange: (redeem: LoyaltyRedeem) => void;
  subtotal: number;
  discountInput: string;
  discountError?: string | null;
  discountAmount: number;
  serviceCharge: number;
  taxRate: number;
  taxAmount: number;
  total: number;
  collectionMode: CollectionMode;
  paidInput: string;
  method: PaymentMethod;
  mixed: MixedAmounts;
  placeDisabled: boolean;
  disabledReason: string | null;
  submitting: boolean;
  onTypeChange: (type: OrderType) => void;
  onDetailsChange: (details: CustomerDetails) => void;
  onQuantityChange: (key: string, delta: number) => void;
  onRemove: (key: string) => void;
  onNoteChange: (key: string, note: string) => void;
  onDiscountChange: (value: string) => void;
  onCollectionModeChange: (mode: CollectionMode) => void;
  onPaidChange: (value: string) => void;
  onMethodChange: (method: PaymentMethod) => void;
  onMixedChange: (field: SplitMethod, value: string) => void;
  onPlaceOrder: () => void;
}) {
  const itemCount = cart.reduce((sum, line) => sum + line.quantity, 0);

  return (
    <aside id={id} className="cashier-cart flex w-full min-w-0 flex-col overflow-hidden rounded-2xl border border-border/70 bg-card shadow-sm" aria-label="الطلب الحالي" aria-labelledby={headingId}>
      {/* Header (fixed) */}
      <div className="flex shrink-0 items-center justify-between border-b px-4 py-3">
        <h2 id={headingId} ref={headingRef} tabIndex={-1} className="rounded text-lg font-bold focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-primary">{t.pos.currentOrder}</h2>
        <Badge variant="secondary" className="tabular-nums">
          {itemCount} {t.pos.items}
        </Badge>
      </div>

      {/* Scroll region: order type + table + customer + cart items */}
      <div className="flex min-h-0 flex-1 flex-col gap-3 overflow-y-auto p-3">
        <OrderTypeSelector
          type={orderType}
          details={details}
          branchId={branchId}
          tableReloadKey={tableReloadKey}
          onTypeChange={onTypeChange}
          onDetailsChange={onDetailsChange}
        />

        {/* Customer profile + loyalty (phone lookup, points redemption) */}
        <details className="rounded-xl bg-muted/35 px-3 py-2">
          <summary className="cursor-pointer text-sm font-semibold">العميل وبرنامج الولاء {details.customerPhone && <bdi dir="ltr">· {details.customerPhone}</bdi>}{redeem.points > 0 && <span> · {redeem.points} نقطة مستخدمة</span>}</summary>
          <div className="pt-3"><CustomerLoyalty
            branchId={branchId}
            phone={details.customerPhone}
            customerName={details.customerName}
            orderTotalBeforeLoyalty={totalBeforeLoyalty}
            previewTotalAfterDiscount={previewTotalAfterDiscount}
            collectionMode={collectionMode}
            redeem={redeem}
            onPhoneChange={(customerPhone) => onDetailsChange({ ...details, customerPhone })}
            onRedeemChange={onRedeemChange}
          /></div>
        </details>

        <div className="space-y-2 border-t pt-3">
          {discountControls}
          {cart.length === 0 ? (
            <div className="flex min-h-20 flex-col items-center justify-center gap-1.5 py-2 text-center">
              <span className="text-2xl">🛒</span>
              <p className="text-sm font-medium">{t.pos.cartEmpty}</p>
              <p className="max-w-48 text-xs text-muted-foreground">
                {t.pos.cartEmptyHint}
              </p>
            </div>
          ) : (
            cart.map((line) => (
              <CartItem
                key={line.key}
                line={line}
                currency={currency}
                onQuantityChange={onQuantityChange}
                onRemove={onRemove}
                onNoteChange={onNoteChange}
              />
            ))
          )}
        </div>
      <div className="border-t pt-3">
        <PaymentSummary
          currency={currency}
          subtotal={subtotal}
          discountInput={discountInput}
          discountError={discountError}
          discountAmount={discountAmount}
          loyaltyPoints={redeem.points}
          loyaltyDiscount={redeem.discount}
          serviceCharge={serviceCharge}
          taxRate={taxRate}
          taxAmount={taxAmount}
          total={total}
          collectionMode={collectionMode}
          paidInput={paidInput}
          method={method}
