'use client';
import { useState } from 'react';
import Link from 'next/link';
import { Search, ArrowUpLeft, FileText } from 'lucide-react';
import { REPORT_GROUPS, type ReportCatalogEntry } from '@/lib/report-center';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';

export function ReportCenter({ reports, branchScoped, configured }: { reports: ReportCatalogEntry[]; branchScoped: boolean; configured: boolean }) {
  const [search, setSearch] = useState(''), [group, setGroup] = useState('all');
  const filtered = reports.filter(report => (group === 'all' || report.group === group) && `${report.title} ${report.description}`.includes(search.trim()));
  return <div className="workspace-page" dir="rtl">
    <header className="workspace-header"><div className="mb-2 flex items-center gap-2 text-primary"><FileText className="size-5" /><span className="text-sm font-medium">NEXT CUP</span></div><h1 className="text-2xl font-bold sm:text-3xl">مركز التقارير</h1><p className="mt-2 max-w-3xl text-sm leading-7 text-muted-foreground">اختر التقرير ثم حدد الفترة والفلاتر داخل شاشته. كل تقرير يستخدم مصدره الأصلي؛ صلاحية التصدير تُراجع عند الطلب.</p><p className="mt-2 text-sm">{branchScoped ? 'التقارير المتاحة ضمن نطاق فرعك. التقارير على مستوى الكافيه مخفية.' : 'التقارير المتاحة حسب صلاحيات حسابك والميزات المفعلة.'}</p></header>
    <div className="grid gap-4 rounded-xl bg-card p-4 sm:grid-cols-[1fr_16rem]"><div className="space-y-2"><Label htmlFor="report-search">ابحث عن تقرير</Label><div className="relative"><Search className="pointer-events-none absolute start-3 top-3 size-4 text-muted-foreground" /><Input id="report-search" className="ps-9" value={search} onChange={event => setSearch(event.target.value)} placeholder="اسم التقرير أو محتواه" /></div></div><div className="space-y-2"><Label htmlFor="report-group">القسم</Label><select id="report-group" className="h-10 w-full rounded-md border bg-background px-3 text-sm" value={group} onChange={event => setGroup(event.target.value)}><option value="all">كل الأقسام</option>{REPORT_GROUPS.map(item => <option key={item.id} value={item.id}>{item.title}</option>)}</select></div></div>
    {!configured && <p role="alert" className="rounded-xl border p-4">إعدادات الكافيه غير متاحة؛ لم يُنشئ مركز التقارير إعدادات تلقائية. راجع المالك.</p>}
    <p className="text-sm text-muted-foreground" role="status">{filtered.length} تقرير أو سجل متاح</p>
    {REPORT_GROUPS.filter(item => group === 'all' || group === item.id).map(item => {
      const rows = filtered.filter(report => report.group === item.id);
      return <section key={item.id} aria-labelledby={'group-' + item.id} className="space-y-3"><div><h2 id={'group-' + item.id} className="text-xl font-semibold">{item.title}</h2><p className="mt-1 text-sm text-muted-foreground">{item.description}</p></div>{rows.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{rows.map(report => <Link key={report.id} href={report.href} className="group flex flex-col rounded-xl border bg-card p-5 transition-colors hover:border-primary hover:bg-primary/5 focus-visible:outline-2 focus-visible:outline-primary"><div className="flex items-start justify-between gap-2"><h3 className="font-semibold">{report.title}</h3><ArrowUpLeft className="size-4 shrink-0 text-primary" /></div><p className="my-3 flex-1 text-sm leading-7 text-muted-foreground">{report.description}</p><span className="text-xs font-medium text-primary">{report.format}</span></Link>)}</div> : <p className="rounded-xl border border-dashed p-5 text-sm text-muted-foreground">{search ? 'لا توجد نتائج مطابقة في هذا القسم.' : 'لا توجد تقارير متاحة لهذا القسم ضمن صلاحياتك والميزات المفعلة.'}</p>}</section>;
    })}
    <p className="rounded-xl border p-4 text-sm leading-7 text-muted-foreground">القوائم المحاسبية تجريبية SHADOW وتعرض حالة الإعداد كما هي. المصروفات والمشتريات والتحصيلات والتحويلات الداخلية لكلٍ منها معنى مستقل؛ لا يجمعها المركز في رصيد أو ربح جديد.</p>
  </div>;
}

'use client';
import {useRef,useState,type ReactNode} from 'react';
import {useApp} from '@/components/app-shell';
import {api} from '@/lib/client';
import {addDays,dateStrInTz} from '@/lib/date-range';
import {businessWindow,transitionIssues,type ReportingHours} from '@/lib/business-day';
import {TouchSelect} from '@/components/pos/touch-select';
import {TouchDateInput} from '@/components/pos/touch-date-input';
import {Button} from '@/components/ui/button';
import {Dialog,DialogContent,DialogTitle,DialogFooter} from '@/components/ui/dialog';

export type ReportingMetadata={mode:string;windows:{branchId?:string;businessDate:string;from:string;to:string;startLocal:string;endLocal:string;timezone:string;warnings:string[];kind:string}[];branches:{id:string;name:string;versions:ReportingHours[]}[];outsideCounts:{branchId:string;orders:number;payments:number;adjustments?:number}[];coverageNote:string};
const zones=['Africa/Cairo','Asia/Riyadh','Asia/Dubai','Asia/Beirut','Asia/Amman','Africa/Casablanca','Europe/London','Europe/Berlin','America/New_York','America/Chicago','America/Los_Angeles','Asia/Kolkata','Australia/Sydney','UTC'];
function TimeInput({label,value,onChange}:{label:string;value:string;onChange:(v:string)=>void}){const [h,m]=value.split(':');return <div className="space-y-1"><span>{label}</span><div className="flex gap-2" dir="ltr"><TouchSelect aria-label={label+' — الساعة'} value={h} onValueChange={v=>onChange(v+':'+m)}>{Array.from({length:24},(_,i)=>String(i).padStart(2,'0')).map(v=><option key={v} value={v}>{v}</option>)}</TouchSelect><span className="self-center">:</span><TouchSelect aria-label={label+' — الدقيقة'} value={m} onValueChange={v=>onChange(h+':'+v)}>{Array.from({length:60},(_,i)=>String(i).padStart(2,'0')).map(v=><option key={v} value={v}>{v}</option>)}</TouchSelect></div></div>;}
function ZoneInput({value,onChange}:{value:string;onChange:(v:string)=>void}){return <div className="space-y-2"><TouchSelect aria-label="المنطقة الزمنية" value={zones.includes(value)?value:'other'} onValueChange={v=>onChange(v==='other'?'':v)}>{zones.map(v=><option key={v} value={v}>{v}</option>)}<option value="other">منطقة أخرى — أدخل اسم IANA</option></TouchSelect>{!zones.includes(value)&&<input className="min-h-12 w-full rounded border p-3" aria-label="اسم المنطقة الزمنية IANA" value={value} onChange={e=>onChange(e.target.value)}/>}</div>;}
export function ReportingControls({filters,onChange,metadata,onSaved,children}:{filters:Record<string,string>;onChange:(f:Record<string,string>)=>void;metadata?:ReportingMetadata|null;onSaved:()=>void;children?:ReactNode}){
 const {canKey}=useApp(),[open,setOpen]=useState(false),[error,setError]=useState(''),[busy,setBusy]=useState(false),[ack,setAck]=useState(false),lock=useRef(false);
 const branch=metadata?.branches.find(b=>b.id===filters.branchId)??(metadata?.branches.length===1?metadata.branches[0]:undefined);
 const [draft,setDraft]=useState<ReportingHours>({startTime:'00:00',endTime:'00:00',is24Hours:true,timezone:'Africa/Cairo',effectiveDate:addDays(dateStrInTz(new Date()),1)});
 const change=(k:string,v:string)=>onChange({...filters,[k]:v});
 function configure(){if(!branch)return;const last=branch.versions.at(-1);setDraft({startTime:last?.startTime??'00:00',endTime:last?.endTime??'00:00',is24Hours:last?.is24Hours??true,timezone:last?.timezone??'Africa/Cairo',effectiveDate:addDays(last&&last.effectiveDate>dateStrInTz(new Date())?last.effectiveDate:dateStrInTz(new Date()),1)});setAck(false);setError('');setOpen(true);}
 let preview='';let issues:ReturnType<typeof transitionIssues>=[];
 try{const w=businessWindow(draft.effectiveDate,draft);preview=`${w.startLocal.replace('T',' ')} ← ${w.endLocal.replace('T',' ')} (${w.timezone}) · ${w.endLocal.slice(0,10)>w.startLocal.slice(0,10)?'الإغلاق في اليوم التالي':'الإغلاق في اليوم نفسه'} · UTC ${w.from.toISOString()} / ${w.to.toISOString()} ${w.warnings.join('؛ ')}`;issues=transitionIssues(draft,branch?.versions??[]);}catch(e){preview=(e as Error).message;}
 async function save(){if(!branch||lock.current)return;lock.current=true;setBusy(true);setError('');try{await api('/api/branches/'+branch.id+'/reporting-hours',{method:'POST',body:{...draft,acknowledgeGap:ack}});setOpen(false);onSaved();}catch(e){setError((e as Error).message);}finally{lock.current=false;setBusy(false);}}
 return <section className="reporting-controls min-w-0 space-y-3" aria-label="فترة تقرير المبيعات">
  <div className="flex flex-wrap items-end gap-3">{children}<label className="flex min-w-48 flex-1 flex-col gap-1 text-sm">نطاق التقرير<TouchSelect aria-label="نطاق التقرير" value={filters.reportMode??metadata?.mode??'business'} onValueChange={v=>{if(v==='legacy'){const next={...filters};delete next.reportMode;onChange(next);}else change('reportMode',v);}}>{metadata?.mode==='legacy'&&<option value="legacy">سجل المبيعات — اختر فترة أعمال للتقرير</option>}<option value="business">أيام العمل — الساعات المحفوظة</option><option value="outside">خارج ساعات التقارير</option><option value="custom">مدة تاريخ/وقت مخصصة — تقرير لمرة واحدة</option></TouchSelect></label>

  </div>

  {(filters.reportMode??metadata?.mode)==='legacy'?null:(filters.reportMode??metadata?.mode)!=='custom'?<div className="flex flex-wrap gap-3"><label>من تاريخ عمل<TouchDateInput label="بداية أيام العمل" value={filters.businessFrom??dateStrInTz(new Date())} onValueChange={v=>onChange({...filters,reportMode:filters.reportMode??'business',businessFrom:v,businessTo:filters.businessTo??v})}/></label><label>إلى تاريخ عمل<TouchDateInput label="نهاية أيام العمل" value={filters.businessTo??filters.businessFrom??dateStrInTz(new Date())} onValueChange={v=>onChange({...filters,reportMode:filters.reportMode??'business',businessTo:v})}/></label></div>:<div className="space-y-3"><p>تقرير مخصص: لا يغيّر ساعات الفرع المحفوظة.</p><div className="flex flex-wrap gap-3">{(['customStart','customEnd'] as const).map((key,i)=><div key={key}><span>{i?'نهاية المدة (غير مشمولة)':'بداية المدة (مشمولة)'}</span><TouchDateInput label={i?'تاريخ نهاية المدة':'تاريخ بداية المدة'} value={filters[key]?.slice(0,10)??''} onValueChange={v=>change(key,v+'T'+(filters[key]?.slice(11)??'00:00'))}/><TimeInput label={i?'وقت نهاية المدة':'وقت بداية المدة'} value={filters[key]?.slice(11)??'00:00'} onChange={v=>change(key,(filters[key]?.slice(0,10)||dateStrInTz(new Date()))+'T'+v)}/></div>)}</div><ZoneInput value={filters.customTimezone??'Africa/Cairo'} onChange={v=>change('customTimezone',v)}/></div>}
  {metadata&&<details className="border-t border-border/60 pt-3 text-sm text-muted-foreground"><summary className="cursor-pointer font-medium">الفترة الفعلية والتغطية وإعدادات الساعات</summary><div className="mt-3 space-y-2" aria-live="polite"><Button variant="outline" onClick={()=>{const from=filters.businessFrom||filters.customStart?.slice(0,10)||dateStrInTz(new Date());onChange({...filters,reportMode:'business',customStart:'',customEnd:'',customTimezone:'',businessFrom:from,businessTo:filters.businessTo||filters.customEnd?.slice(0,10)||from,from:'',to:''});}}>العودة إلى الساعات المحفوظة</Button><b>{metadata.mode==='custom'?'تقرير مخصص':metadata.mode==='outside'?'تقرير خارج الساعات':'فترة التقرير الفعلية'} — البداية مشمولة، النهاية مستبعدة</b><details><summary>الفترات الفعلية ({metadata.windows.length})</summary>{metadata.windows.map((w,i)=><p key={i} className="break-words" dir="auto">{metadata.branches.find(b=>b.id===w.branchId)?.name} · {w.startLocal.replace('T',' ')} → {w.endLocal.replace('T',' ')} · {w.timezone}<br/><span dir="ltr">UTC {w.from} → {w.to}</span>{w.warnings.map(s=><span key={s} className="block">{s}</span>)}</p>)}</details><p>{metadata.coverageNote}</p><p>خارج الساعات ضمن التغطية: {metadata.outsideCounts.reduce((s,r)=>s+r.orders,0)} فواتير · {metadata.outsideCounts.reduce((s,r)=>s+r.payments,0)} حركات دفع · {metadata.outsideCounts.reduce((s,r)=>s+(r.adjustments??0),0)} تعديلات فواتير. لا تضاف تلقائيًا إلى أيام العمل.</p>{canKey('settings.edit')&&<><Button variant="outline" disabled={!branch} onClick={configure}>تغيير ساعات تقارير الفرع</Button>{!branch&&<p>اختر فرعًا واحدًا لتعديل إعداداته.</p>}</>}</div></details>}
