 function filterValue(key:string,value:string){if(key==='branchId')return list.branches.find(b=>b.id===value)?.name??value;if(key==='userId')return list.users.find(u=>u.id===value)?.name??value;return statusName[value]??({CASH:'نقدي',CARD:'بطاقة',WALLET:'محفظة',business:'أيام العمل',outside:'خارج الساعات',custom:'مدة مخصصة'} as Record<string,string>)[value]??value;}
