 function startEdit(){if(!detail)return;const o=detail.order;setStageKey(crypto.randomUUID());setPreview(null);setEdit({baseRevision:o.revision,reason:'',invoiceDiscount:{type:(o.invoiceDiscountType??(Number(o.discountAmount)>0?'FIXED':'NONE')) as 'NONE'|'PERCENT'|'FIXED',value:o.invoiceDiscountValue??o.discountAmount},items:o.items.map(i=>({id:i.id,quantity:i.quantity,unitPrice:i.unitPrice,discount:{type:i.itemDiscountType as 'NONE'|'PERCENT'|'FIXED',value:i.itemDiscountValue}}))});}
 function change(next:AmendmentInput){setEdit(next);setPreview(null);}
