   <div className="flex flex-wrap items-center justify-between gap-3 border-t border-border/70 px-4 py-3"><p className="text-sm text-muted-foreground">صفحة {page} / {hasCurrent?Math.max(1,Math.ceil(list.count/30)):'—'} · 30 فاتورة كحد أقصى للصفحة</p><div className="flex gap-2"><Button variant="outline" disabled={reportLoading||page<=1} onClick={()=>setPage(page-1)}>السابق</Button><Button variant="outline" disabled={reportLoading||!hasCurrent||page*30>=list.count} onClick={()=>setPage(page+1)}>التالي</Button></div></div>
  </section>
