   <div className="flex flex-wrap gap-2">{canKey('sales.edit')&&<Button disabled={busy} onClick={startEdit}>تعديل الفاتورة</Button>}{canKey('receipts.print')&&<Button variant="outline" onClick={()=>void showReceipt(detail.order.revision)}>الفاتورة الحالية</Button>}{canKey('receipts.reprint')&&<Button variant="outline" onClick={()=>void showReceipt(0)}>الفاتورة الأصلية</Button>}{canKey('audit.view')&&<Link className="underline self-center" href={'/tracing?q='+encodeURIComponent(detail.order.id)}>سجل التتبّع</Link>}</div>
