    <div className="flex flex-wrap gap-2"><TouchSelect aria-label="إضافة منتج" className={inputClass} value={newProduct} onValueChange={touchValue => {setNewProduct(touchValue);setNewVariant('');setNewAdds([]);}}><option value="">إضافة صنف</option>{detail.products.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</TouchSelect><TouchSelect aria-label="الحجم الجديد" className={inputClass} value={newVariant} onValueChange={touchValue => setNewVariant(touchValue)}><option value="">الحجم</option>{detail.products.find(p=>p.id===newProduct)?.variants.map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</TouchSelect>{detail.products.find(p=>p.id===newProduct)?.addOns.filter(a=>a.addOn.isActive).map(({addOn:a})=><label key={a.id}><input type="checkbox" checked={newAdds.includes(a.id)} onChange={e=>setNewAdds(e.target.checked?[...newAdds,a.id]:newAdds.filter(id=>id!==a.id))}/>{a.name}</label>)}<Button variant="outline" disabled={!newProduct} onClick={()=>{change({...edit,items:[...edit.items,{id:'new-'+crypto.randomUUID(),productId:newProduct,variantId:newVariant||null,addOnIds:newAdds,quantity:1,discount:{type:'NONE',value:'0'}}]});}}>إضافة</Button></div>
    <label className="block">خصم الفاتورة<DiscountInput label="خصم الفاتورة" value={edit.invoiceDiscount} onChange={v=>change({...edit,invoiceDiscount:v})}/></label><label className="block">سبب التعديل (إلزامي)<textarea aria-label="سبب التعديل" className={inputClass+' block w-full'} value={edit.reason} maxLength={500} onChange={e=>change({...edit,reason:e.target.value})}/></label>
    <Button disabled={busy||edit.reason.trim().length<3} onClick={()=>void run(async()=>{const result=await api<{proposed:Proposed}>('/api/sales/'+detail.order.id,{method:'POST',body:{action:'preview',input:edit}});setPreview(result.proposed);})}>معاينة الفرق</Button>
    {preview&&<div className="space-y-3 rounded bg-muted p-3"><h3 className="font-bold">قبل / بعد</h3><table className="w-full text-sm"><thead><tr><th>القيمة</th><th>قبل</th><th>بعد</th></tr></thead><tbody>{[['إجمالي الأصناف',detail.order.subtotal,preview.subtotal],['الخصم',detail.order.discountAmount,preview.discountAmount],['الإجمالي النهائي',detail.order.total,preview.total]].map(([label,before,after])=><tr key={label}><td>{label}</td><td>{money(before)}</td><td>{money(after)}</td></tr>)}</tbody></table>{preview.lines.map(l=>{const old=detail.order.items.find(i=>i.id===l.id);return <p className="text-sm" key={l.id}>{l.productName}: كمية {old?.quantity??0} ← {l.quantity} · سعر {money(old?.unitPrice)} ← {money(l.unitPrice)} · خصم {discountName[old?.itemDiscountType??'NONE']} {old?.itemDiscountValue??0} ← {discountName[l.discount.type]} {l.discount.value}</p>;})}<p>التسوية: {preview.settlement.direction==='REFUND'?'مرتجع':preview.settlement.direction==='COLLECTION'?'تحصيل إضافي':'بدون حركة مالية'} {money(preview.settlement.amount)} · المتبقي بعد التسوية {money(preview.settlement.remaining)}</p><p className="text-sm">إضافات تحضير: {preview.positiveLines.map(l=>`${l.productName} × ${l.quantity}`).join('، ')||'لا يوجد'} · كمية محذوفة: {preview.quantityRemoved.reduce((s,r)=>s+r.quantity,0)}. لا تُعاد خامات المشروبات المحضرة تلقائيًا.</p><Button disabled={busy} onClick={()=>void run(async()=>{await api('/api/sales/'+detail.order.id,{method:'POST',body:{action:'stage',input:edit,requestKey:stageKey}});setEdit(null);setPreview(null);await reloadDetail(detail.order.id);})}>حفظ طلب التعديل</Button></div>}
   </section>}
   {detail.amendments.map(a=>{const attempt=detail.attempts.filter(t=>t.amendmentId===a.id).at(-1),own=a.requesterId===user.id;return <section key={a.id} className="space-y-2 rounded border p-3"><div className="flex justify-between"><b>{statusName[a.status]??a.status}</b><span className="text-xs">{formatDateTime(a.createdAt)}</span></div><p>{a.reason} · إجمالي مقترح {money(a.proposed.total)}</p>
    {a.status!=='COMMITTED'&&a.status!=='CANCELLED'&&<>
     {a.approvalRequired&&!a.approverId&&<p>موافقة المدير مطلوبة</p>}{canKey('sales.approve')&&!a.approverId&&<Button disabled={busy} onClick={()=>void run(()=>action(a.id,{action:'approve'}))}>اعتماد المدير</Button>}
     {detail.requests.filter(r=>r.id===a.ownerRequestId||r.id===a.ownerVoidRequestId).map(r=><div key={r.id} className="rounded border p-2"><p>موافقة المالك {r.action.includes('REFUND')?'على المرتجع':'على إزالة الصنف'}: {statusName[r.status]??r.status} ({r.mode})</p>{r.status==='PENDING'&&r.ownerId===user.id&&r.mode!=='OWNER_PASSCODE'&&<Button disabled={busy} onClick={()=>void run(async()=>{await api('/api/owner-action-requests/'+r.id+'/decision',{method:'POST',body:{decision:'ACCEPT',note:'اعتماد التعديل المقترح بالمبيعات'}});await reloadDetail(detail.order.id);})}>موافقة المالك</Button>}{r.status==='PENDING'&&own&&r.mode!=='OWNER_REQUEST'&&<div className="flex gap-2"><input aria-label="رمز موافقة المالك" type="password" className={inputClass} value={passcode} autoComplete="off" onChange={e=>setPasscode(e.target.value)}/><Button disabled={busy} onClick={()=>void run(async()=>{await api('/api/owner-action-requests/'+r.id+'/passcode',{method:'POST',body:{passcode}});setPasscode('');await reloadDetail(detail.order.id);})}>اعتماد الرمز</Button></div>}</div>)}
     {(own||(attempt&&["PENDING","UNKNOWN"].includes(attempt.status)&&canKey("sales.approve")))&&<div className="space-y-2">{own&&a.proposed.settlement.direction!=='NONE'&&(!attempt||attempt.status==='FAILED')&&<div className="flex gap-2"><TouchSelect aria-label="وسيلة التسوية" className={inputClass} value={method} onValueChange={touchValue => setMethod(touchValue as typeof method)}><option value="CASH">كاش</option><option value="CARD">كارت</option><option value="WALLET">محفظة</option></TouchSelect><Button disabled={busy} onClick={()=>void run(async()=>{const key=attemptKeys[a.id]??crypto.randomUUID();setAttemptKeys({...attemptKeys,[a.id]:key});await action(a.id,{action:'begin',requestKey:key,method});})}>بدء التسوية وحجز الطلب</Button></div>}
      {attempt&&<div className="rounded bg-muted p-3"><b>{statusName[attempt.status]??attempt.status}</b><p>{attempt.direction==='REFUND'?'أعد':'حصّل'} {money(attempt.amount)} حسب: {attempt.legs.map(l=>`${l.method} ${money(l.amount)}`).join(' + ')}</p>{['PENDING','UNKNOWN'].includes(attempt.status)&&<><p className="text-sm">نفّذ الحركة الفعلية مرة واحدة. عند الشك اختر «غير مؤكد» وراجع التسوية قبل إعادة المحاولة.</p><label className="block"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> أؤكد أن الأموال تحركت فعليًا بالقيم والوسائل المعروضة</label><input aria-label="مرجع التسوية" placeholder="مرجع العملية الإلكترونية" className={inputClass+' w-full'} value={reference} onChange={e=>setReference(e.target.value)}/>{[...new Set(attempt.legs.map(l=>l.method).filter(m=>m!=="CASH"))].length>1&&[...new Set(attempt.legs.map(l=>l.method).filter(m=>m!=="CASH"))].map(m=><input key={m} aria-label={"مرجع "+m} placeholder={"مرجع مستقل "+m} className={inputClass+" w-full"} value={references[m]??""} onChange={e=>setReferences({...references,[m]:e.target.value})}/>)}<input aria-label="ملاحظة التسوية" placeholder="ملاحظة / سبب الفشل أو عدم التأكد" className={inputClass+' w-full'} value={attemptNote} onChange={e=>setAttemptNote(e.target.value)}/><div className="flex flex-wrap gap-2">{(['CONFIRMED','FAILED','UNKNOWN'] as const).map(outcome=><Button key={outcome} variant={outcome==='CONFIRMED'?'default':'outline'} disabled={busy||(outcome==='CONFIRMED'&&!confirmed)} onClick={()=>void run(async()=>{await action(a.id,{action:'observe',attemptId:attempt.id,outcome,evidence:{confirmed,reference,references,note:attemptNote}});if(outcome==='FAILED')setAttemptKeys({...attemptKeys,[a.id]:crypto.randomUUID()});setConfirmed(false);setReference('');setReferences({});setAttemptNote('');})}>{outcome==='CONFIRMED'?'تأكيد الحركة الفعلية':outcome==='FAILED'?'فشل — لم تتحرك أموال':'غير مؤكد'}</Button>)}</div></>}</div>}
      {own&&<><Button disabled={busy||(a.proposed.settlement.direction!=='NONE'&&attempt?.status!=='OBSERVED')} onClick={()=>void run(async()=>{await action(a.id,{action:'commit'});toast.success('تم حفظ المراجعة والتسوية');})}>{attempt?.status==='OBSERVED'?'حفظ التعديل بعد التسوية — دون حركة أموال أخرى':'اعتماد التعديل بدون حركة أموال'}</Button><Button variant="outline" disabled={busy} onClick={()=>void run(()=>action(a.id,{action:'cancel'}))}>إلغاء الطلب غير المنفذ</Button></>}
     </div>}
     {!own&&attempt?.status==="OBSERVED"&&canKey("sales.approve")&&<Button disabled={busy} onClick={()=>void run(()=>action(a.id,{action:"commit"}))}>استكمال حفظ التسوية المؤكدة للموظف — بدون حركة أموال جديدة</Button>}
    </>}
   </section>;})}
  </DialogContent></Dialog>}
  {receipt&&<RevisionReceipt receipt={receipt} close={()=>setReceipt(null)}/>}
 </div>;
