type RegisterSale=Pick<Sale,'id'|'orderNumber'|'createdAt'|'branch'|'createdBy'|'paymentStatus'|'total'|'paidAmount'|'remainingAmount'|'revision'>;
export function SalesRegister({orders,busy,onOpen}:{orders:RegisterSale[];busy:boolean;onOpen:(id:string)=>void}){
 return <div className="overflow-x-auto" role="region" aria-label="جدول الفواتير — قابل للتمرير أفقيًا" tabIndex={0}><table className="workspace-table w-full min-w-[800px] text-start text-sm"><caption className="sr-only">الفواتير المطابقة مرتبة من الأحدث؛ التحصيل والمتبقي محفوظان لكل فاتورة.</caption><thead><tr>{['الفاتورة / الوقت','الفرع / الكاشير','حالة الدفع','الإجمالي','المحصّل','المتبقي','الإجراءات'].map(label=><th key={label} scope="col" className="whitespace-nowrap bg-muted/40 px-4 py-3 text-start font-medium text-muted-foreground">{label}</th>)}</tr></thead><tbody>{orders.map(o=><tr key={o.id} className="border-t border-border/60 hover:bg-muted/20"><td className="px-4 py-4"><button type="button" className="min-h-11 font-bold text-primary underline-offset-4 hover:underline" disabled={busy} aria-label={'عرض الفاتورة #'+o.orderNumber} onClick={()=>onOpen(o.id)}><bdi>#{o.orderNumber}</bdi></button><p className="whitespace-nowrap text-xs text-muted-foreground"><bdi>{formatDateTime(o.createdAt)}</bdi></p>{o.revision>0&&<span className="mt-1 inline-block rounded bg-caramel-soft px-2 py-1 text-xs text-caramel-ink">مراجعة {o.revision}</span>}</td><td className="max-w-52 px-4 py-4"><p className="break-words font-medium">{o.branch.name}</p><p className="mt-1 break-words text-xs text-muted-foreground">{o.createdBy?.name??'طلب عميل'}</p></td><td className="px-4 py-4"><span className={cn('inline-flex whitespace-nowrap rounded-full px-2.5 py-1 text-xs font-medium',o.paymentStatus==='PAID'?'bg-sage-soft text-sage-ink':o.paymentStatus==='REFUNDED'?'bg-clay-soft text-clay-ink':'bg-caramel-soft text-caramel-ink')}>{statusName[o.paymentStatus]??o.paymentStatus}</span></td><td className="whitespace-nowrap px-4 py-4 font-semibold tabular-nums"><bdi>{money(o.total)}</bdi></td><td className="whitespace-nowrap px-4 py-4 tabular-nums"><bdi>{money(o.paidAmount)}</bdi></td><td className="whitespace-nowrap px-4 py-4 tabular-nums"><bdi>{money(o.remainingAmount)}</bdi></td><td className="px-4 py-4"><Button variant="outline" disabled={busy} onClick={()=>onOpen(o.id)}>تفاصيل / إيصال</Button></td></tr>)}</tbody></table></div>;
}
function Metric({label,value}:{label:string;value:string}){return <div className="workspace-surface p-4"><p className="text-sm text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-bold tabular-nums"><bdi>{value}</bdi></p></div>;}
function ItemTable({items}:{items:Item[]}){return <div className="overflow-x-auto"><table className="w-full text-right text-sm"><thead><tr>{['الصنف','الوحدة','الكمية','الخصم','إجمالي الصنف بعد خصمه','نصيب خصم الفاتورة'].map(h=><th key={h} className="p-2">{h}</th>)}</tr></thead><tbody>{items.map(i=><tr key={i.id} className="border-t"><td className="p-2">{i.productName} {i.variantName} {i.addOns.map(a=>a.addOnName).join(' + ')}</td><td>{money(i.unitPrice)}</td><td>{i.quantity}</td><td>{discountName[i.itemDiscountType]??i.itemDiscountType} {i.itemDiscountValue} ({money(i.itemDiscountAmount)})</td><td>{money(i.lineTotal)}</td><td>{money(i.invoiceDiscountShare)}</td></tr>)}</tbody></table></div>;}
function Totals({sale}:{sale:Sale}){return <div className="flex flex-wrap gap-4 border-t pt-2 text-sm"><span>قبل الخصم {money(sale.subtotal)}</span><span>إجمالي الخصومات {money(sale.discountAmount)}</span><span>خدمة {money(sale.serviceChargeAmount)}</span><span>ضريبة {money(sale.taxAmount)}</span><b>إجمالي الفاتورة {money(sale.total)}</b></div>;}

function RevisionReceipt({receipt,close}:{receipt:{orderId:string;revision:number;snapshot:Sale};close:()=>void}){
 const frame=useRef<HTMLIFrameElement>(null),[printing,setPrinting]=useState(false),[error,setError]=useState('');
 async function print(){if(printing)return;setPrinting(true);try{await api('/api/sales/'+receipt.orderId+'/receipt',{method:'POST',body:{revision:receipt.revision,reprint:true,logPrint:true}});frame.current?.contentWindow?.focus();frame.current?.contentWindow?.print();}catch(e){setError(e instanceof Error?e.message:'تعذر الطباعة');}finally{setPrinting(false);}}
 const escape=(s:unknown)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
 const o=receipt.snapshot;
 const html=`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>فاتورة ${escape(o.orderNumber)} مراجعة ${receipt.revision}</title><style>body{font:14px Arial;margin:20px}table{width:100%;border-collapse:collapse}td,th{padding:8px;border-bottom:1px solid #ddd;text-align:right}@media print{body{margin:0}}</style><h2>NEXT CUP</h2><h3>فاتورة #${escape(o.orderNumber)} — مراجعة ${receipt.revision}</h3><p>${escape(receipt.orderId)}</p><p>${escape(o.createdBy?.name)} · ${escape(o.branch?.name)} · ${escape(formatDateTime(o.createdAt))}</p><table><tr><th>الصنف</th><th>الكمية</th><th>الوحدة</th><th>الخصم</th><th>الإجمالي</th></tr>${o.items.map(i=>`<tr><td>${escape(i.productName)} ${escape(i.variantName)}</td><td>${i.quantity}</td><td>${escape(money(i.unitPrice))}</td><td>${escape(money(i.itemDiscountAmount))}</td><td>${escape(money(i.lineTotal))}</td></tr>`).join('')}</table><p>قبل الخصم ${escape(money(o.subtotal))}</p><p>الخصومات ${escape(money(o.discountAmount))} · الخدمة ${escape(money(o.serviceChargeAmount))} · الضريبة ${escape(money(o.taxAmount))}</p><h3>الإجمالي ${escape(money(o.total))}</h3><p>صافي التحصيل ${escape(money(o.paidAmount))} · المتبقي ${escape(money(o.remainingAmount))}</p></html>`;
 return <Dialog open onOpenChange={v=>!v&&close()}><DialogContent className="sm:max-w-xl" dir="rtl"><DialogTitle>الفاتورة — مراجعة {receipt.revision}</DialogTitle><iframe title="معاينة الفاتورة المعدلة" ref={frame} srcDoc={html} className="h-[55vh] w-full rounded border"/>{error&&<p role="alert">{error}</p>}<div className="flex gap-2"><Button disabled={printing} onClick={()=>void print()}>طباعة / إعادة طباعة</Button><Button variant="outline" onClick={close}>إغلاق بدون طباعة</Button></div></DialogContent></Dialog>;
}
